programs.haiku:
"""Word-continuation fragments: short letter pieces that continue a word begun by an earlier token.

The component fires on the second or later piece of a word that has been split into tokens,
when that piece is a short Latin/Cyrillic/Greek fragment. Single letters fire most, then
two-letter fragments that begin with a vowel letter, then three-letter ones."""
READS = ()

VOWELS = set("aeiouyаеёиоуыэюяαεηιοωυ")


def is_letters(s):
    return s.isalpha() and all(ord(c) < 0x250 or 0x370 <= ord(c) < 0x500 for c in s)


def step(carry, prefix, upstream):
    if len(prefix.token_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        carry = None
    before = carry or ""  # letters of the current word that came before this token
    tok = prefix.token_strings[-1]
    core = tok.strip().lower()
    value = 0.0
    if is_letters(core) and not tok[:1].isspace():
        if before:
            n = len(core)
            vowel_start = core[0] in VOWELS
            vowel_end = core[-1] in VOWELS
            if n == 1:
                value = 0.38 if core in VOWELS else 0.2
            elif n == 2 and vowel_start:
                value = 0.19 if vowel_end else 0.33
            elif n == 3 and vowel_start:
                value = 0.19 if vowel_end else 0.1
        return before + core, value
    if is_letters(core):
        return core, value
    return "", value

programs.sol:
"""A lexical access signal and its immediate grammatical continuation.

Access itself is strongly negative; its inflections, programming terms,
translations, and vocabulary about permission, obtaining and using things
have weaker signals. 'Open access' is weaker than 'have/get access'.
A little signal persists into the next article, preposition or word ending.
Everything else is predicted as zero; this omits many small lexical effects.
"""
READS = ()

# These are access/use translations or stems, not arbitrary vocabulary IDs.
ACCESS_TRANSLATIONS = {
    '访问': -2.5, 'アクセス': -3.2, 'アクセ': -0.9,
    'acceso': -2.0, 'acces': -2.2, 'acesso': -2.7, 'acess': -2.4,
    'доступ': -1.6, 'dostęp': -1.6, 'الوصول': -1.0,
}
USE_STEMS = {'使用', '利用', 'ご利用', 'использ', 'ользоват', 'примен',
             'gebruik', '이용', 'ใช'}

# Fractions of the preceding access signal carried by grammatical endings.
ECHO = {
    ' to': 0.325, ' of': 0.27, ' the': 0.25,
    ' a': 0.12, ' an': 0.12, ' for': 0.07,
    ' it': 0.07, ' your': 0.05, ' this': 0.07,
    'ing': 0.68, 'es': 0.47, 'or': 0.18, 'ors': 0.15,
    'o': 0.28, 'ion': 0.12, 'ible': 0.09, 'ibility': 0.05,
}


def lexical_signal(token):
    bare = token.strip()
    stem = bare.lstrip('._/(-')
    word = stem.lower()
    if word == 'access':
        if stem.isupper():
            return -5.4
        if bare.startswith(('(', '.A')):
            return -4.4
        if bare.startswith(('/', '_', '.')):
            return -5.5
        return -6.4 if stem[0].isupper() else -6.1
    if word in {'accessed', 'accessing', 'accesses'}:
        return -5.0
    if word == 'ccess':
        return -2.9  # separately tokenized tail of access
    if word in {'accessor', 'accessors'}:
        return -3.5 if stem[0].isupper() else -2.35
    if word in {'accessible', 'accessibility'}:
        return -1.15
    if word == 'inaccessible':
        return -1.6
    # Access-token and access-exception names are common in source code.
    if word in {'accessory', 'accesstoken'}:
        return -1.1
    if word == 'accessexception':
        return -2.4
    if word == 'accession':
        return -1.7
    if word == 'accessories':
        return -0.45
    if word in ACCESS_TRANSLATIONS:
        return ACCESS_TRANSLATIONS[word]
    if word.startswith('unlock') or word in {'权限', '获取', '解锁', '接入'}:
        return -1.0
    if word in {'访', '訪'}:
        return -0.65
    if word in USE_STEMS or word == 'utilization':
        return -0.5
    if word == 'permissions':
        return -0.85
    if word in {'permission', 'consent', 'entitlement'}:
        return -0.3
    if word in {'unauthorized', 'privileges', 'bypass'}:
        return -0.45
    if word.startswith('obtain') or word in {'acquired', 'utilized', 'utilizing'}:
        return -0.25
    if word in {'possession', 'possessed', 'retrieval'}:
        return -0.55
    if word.startswith(('possess', 'retriev', 'borrow')):
        return -0.35
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, strength = ('', 0.0)
    if carry and carry[0] == doc:
        _, previous, strength = carry
    token = prefix.token_strings[-1]
    word = token.strip().lstrip('._/(-').lower()
    value = lexical_signal(token)
    if word == 'access':
        if previous == 'open':
            value += 1.2
        elif previous in {'have', 'has', 'had'}:
            value -= 0.5
        elif previous in {'get', 'full', 'free', 'public'}:
            value -= 0.9
    native = value
    if previous in {'access', 'accessed', 'accessing', 'accesses', 'accessible'}:
        fraction = ECHO.get(token, 0.0)
        if previous in {'accessing', 'accesses'}:
            fraction *= 0.8
        value += strength * fraction
    return (doc, word, native), float(value)

programs.luna:
"""Approximate a sparse access/use feature, strongest on English “access”."""

READS = ()
BASELINE = -0.00171
ACCESS_USE_STEMS = (
    "访问", "アクセス", "使用", "利用", "использ", "примен", "gebruik",
    "обращ", "запрос",
)


def clean(text):
    return text.casefold().strip().strip("_.,:;!?()[]{}<>\"'`-–—")


def step(carry, prefix, upstream):
    word = clean(prefix.token_strings[-1])
    if word == "access":
        return None, -5.8
    if word in ("accessible", "accessibility"):
        return None, -1.1
    if word.startswith("access") or word.startswith("inaccess"):
        return None, -1.2

    if prefix.position and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = clean(prefix.token_strings[-2])
        if previous == "access" and word == "to":
            return None, -2.2
        if previous == "access" and word == "es":
            return None, -2.9

    if word == "访问":
        return None, -2.4
    if word == "アクセス":
        return None, -2.9
    if word.startswith("permission"):
        return None, -0.5
    if word.startswith("retriev"):
        return None, -0.8
    if word.startswith("unlock"):
        return None, -1.0
    if any(stem in word for stem in ACCESS_USE_STEMS):
        return None, -0.5
    return None, BASELINE

programs.sol:
"""Detect F/f as a letter or short fragment, rather than ordinary words.

Capital F is strongest, especially at a document's start; f is weaker.
The response is smaller inside an uppercase abbreviation. A little of the
signal survives onto the immediately following token, especially when that
token continues the same word. Other scripts' f letters respond more weakly.
"""
READS = ()

# Familiar words and code keywords are not isolated letter fragments.
SHORT_WORDS = {
    'of', 'if', 'for', 'from', 'off', 'self', 'half',
    'few', 'far', 'fun', 'fix', 'def', 'ref',
}


def token_response(token):
    letters = ''.join(c for c in token if c.isalpha())
    n = len(letters)
    if not n:
        return 0.0
    if letters.lower() in SHORT_WORDS:
        return 0.65 if letters == 'IF' else 0.1 if letters.isupper() else 0.0
    if letters in {'F', 'f'}:
        plain = token.strip() == letters
        return (2.1 if plain else 1.9) if letters == 'F' else (1.18 if plain else 1.4)
    if 'F' in letters:
        if n == 2:
            if letters.startswith('F') and letters[1].lower() not in 'aeiouy':
                return 0.6 if token.startswith(' ') else 0.4
            return 0.9
        return 0.5 if n == 3 else 0.12
    if 'f' in letters:
        if letters.endswith('ff'):
            return 0.25 if n == 2 else 0.0
        if n <= 3 and letters.endswith('f'):
            return 0.65 if n == 2 else 0.4
        if n == 2:
            return 0.4 if letters[-1] in 'aeiou' else 0.15
        return 0.05 if letters.startswith('f') else 0.0
    if letters == 'Ф':
        return 1.25
    if any(c in letters for c in 'фفフ'):
        return 0.8 if n == 1 else 0.25
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, 0, '', 0.0)
    _, position, previous_word, pulse = carry
    token = prefix.token_strings[-1]
    value = token_response(token)
    letter = token.strip()
    if letter in {'F', 'f'}:
        inside_word = token[:1].isalpha() and bool(previous_word)
        if position == 0:
            if letter == 'F':
                value = 5.09 if token == 'F' else 4.01
            else:
                value = 3.06 if token == 'f' else 2.57
        elif letter == 'F':
            value = 1.6 if inside_word and previous_word.isupper() else 2.15
        else:
            value = 1.05 if inside_word else 1.22
        if 0 < position < 10:
            value += 0.3 if letter == 'F' else 0.15

    # Carry a one-token echo only for tokens consisting of the letter F/f.
    bare = ''.join(c for c in token if c.isalpha()) in {'F', 'f'}
    next_pulse = value if bare else 0.0
    value += pulse * (0.22 if token[:1].isalpha() else 0.04)
    start = len(token)
    while start and token[start - 1].isalpha():
        start -= 1
    word = (previous_word + token if start == 0 else token[start:])[-30:]
    return (document, position + 1, word, next_pulse), value

programs.luna:
"""Predict a pulse for an F/f letter token, even when punctuation or digits cling to it.
A longer token beginning with capital F gets a smaller pulse."""
READS = ()

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    letters = [char for char in token if char.isalpha()]
    if letters == ['F']:
        return None, 2.0
    if letters == ['f']:
        return None, 1.1
    if token.startswith('F'):
        return None, 0.24
    if 'F' in token or 'f' in token:
        return None, 0.03
    return None, 0.0

programs.sol:
"""A spelling cue, not a topic detector: short vowel-free Latin groups are
usually negative, especially unfamiliar consonant combinations at a word boundary.
English syllable parts are milder, as are fragments inside longer spellings.
Metric symbols and file-operation commands are calibrated separately. FIG is
a positive figure-label cue; initial document positions weaken negative cues.
"""
READS = ()
CONSONANTS = frozenset('bcdfghjklmnpqrstvwxz')
STOPS = frozenset('bcdgkpt')
ONSETS = frozenset('''bl br ch cl cr dr fl fr gl gr ph pl pr sc sh sk sl sm
sn sp st sw th tr tw wh wr kn gn kh zh rh kl kr'''.split())
ENDINGS = frozenset('''bb bs cc ck ct dd ff ft gg gs ks kt ld lf lk ll lm
ln lp ls lt mb mm mn mp ms nc nd ng nk nn ns nt pp ps pt rb rc rd rf rg
rk rl rm rn rp rr rs rt rz sh sk sp ss st th ts tt zz'''.split())
FAMILIAR_CODE = frozenset('''cmd str std src www http html npm xml sql
css ctx tmp msg'''.split())


def token_value(raw):
    word = raw.strip(' \t\r\n._/(=\"\'[]{}:,<>-')
    text = word.lower()
    space = raw.startswith(' ')
    if word == 'FIG':
        return 1.10 if space else 0.94
    if word == 'Fig':
        return 0.15
    # Metric symbols: tiny gram units, length units, and pixels.
    if word in ('mg', 'pg', 'fg'):
        return -1.10
    if word == 'kg':
        return -0.36 if space else -0.24
    if word in ('cm', 'mm', 'km', 'nm'):
        return -0.49 if space else -0.25
    if word == 'px':
        return -0.98
    if word == 'mL' or (word == 'ml' and not space):
        return -0.10
    if word in ('Mr', 'Mrs', 'Dr'):
        return -0.18
    # Short file-operation shell commands.
    if word in ('cd', 'df', 'mv'):
        return -0.70 if not space else -0.85
    if not (2 <= len(text) <= 4 and set(text) <= CONSONANTS):
        return 0.0
    if text in FAMILIAR_CODE or text in ('hmm', 'mmm', 'sch', 'schw', 'schn'):
        return 0.0
    if text in ONSETS:
        value = -0.03
        if text in ENDINGS:
            value -= 0.15 * space
    elif text in ENDINGS:
        value = -0.13 - 0.31 * space
    else:
        value = -0.36 - 0.25 * space
        value += 0.32 * (len(text) >= 3)
        value -= 0.22 * (text[0] in 'bp')
        value -= 0.10 * (text[0] in 'mt')
        value += 0.12 * text.endswith('s')
        value += 0.05 * (text[-1] in 'lr')
        value -= 0.13 * (text[-1] in 'xj')
        # Unlike familiar clusters, two different stop consonants are awkward.
        if len(text) == 2 and text[0] != text[1] and set(text) <= STOPS:
            value -= 0.15
    value -= 0.18 * ('v' in text)
    return value


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    value = token_value(raw)
    new_document = carry is None or carry[0] != doc
    previous = '' if new_document else carry[1]
    if value < 0.0:
        if new_document:
            value *= 0.24
        elif raw and raw[0].isascii() and raw[0].isalpha():
            # Within a longer spelling, the fragment is a weaker cue.
            if previous[-1:].isascii() and previous[-1:].isalpha():
                value *= 0.70
                if previous and set(previous.lower()) <= CONSONANTS:
                    value *= 0.85
            elif previous.endswith('\\'):
                value *= 0.50
            elif previous.endswith('\n'):
                value *= 1.50
    return (doc, raw), value

programs.luna:
"""Use a restrained signal for short uppercase abbreviations and figure labels."""
READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    if word == "FIG":
        return None, 0.55
    if word.isascii() and word.isalpha() and 2 <= len(word) <= 5:
        if any(ch.isupper() for ch in word):
            return None, -0.035
    return None, 0.0

programs.haiku:
"""Chinese content characters: the component fires on a single CJK character that is part
of a word (a noun or other content morpheme), and stays silent on function words.

Measured on training text: a single Han character that is not a common function word
(的, 是, 了, 在, 和, 我, ...) averages about 0.42 when the character before it is also
Han (the second or later character of a Chinese word), about 0.2 after other non-ASCII
text, and about 0.06 when the character before it is ASCII or a space (the first Chinese
character after English). It is weaker after a function word. Hangul syllables behave
like the Han case, weaker. Everything else, including English and code, stays near 0.
"""
import unicodedata

READS = ()

# Common Chinese function words and particles, on which the component stays silent.
FUNCTION_WORDS = set(
    "的是了在和我他你她它们也就都很一个着到而吗呢吧啊没有这那要会与或并等又把被让给从对向上下中为以及但却才还更最不将已其此于之"
)


def _is_han(s):
    return len(s) == 1 and "CJK" in unicodedata.name(s, "")


def _is_hangul(s):
    return len(s) == 1 and unicodedata.name(s, "").startswith("HANGUL")


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""
    if cur in FUNCTION_WORDS or not (_is_han(cur) or _is_hangul(cur)):
        return carry, 0.0
    if not _is_han(cur):
        return carry, 0.2
    if prev in FUNCTION_WORDS:
        return carry, 0.18
    if _is_han(prev):
        return carry, 0.42
    if prev == "" or prev.isascii():
        return carry, 0.06
    return carry, 0.2

programs.sol:
"""Detect the completion of 'instance of', with weaker exemplar phrases.

The main pulse is on 'of' after 'instance' or 'instances'. Related phrases
such as 'example of', 'version of', and 'representation of' get smaller
pulses. The word 'instance' itself gets a small positive value. Other
small lexical fluctuations are left at zero. State resets by document.
"""
import re

READS = ()

EXAMPLES = {"example", "examples", "illustration", "illustrations"}
VERSIONS = {"version", "versions", "variant", "variants", "copies"}
REPRESENTATIONS = {
    "case", "cases", "type", "types", "form", "forms", "class", "classes",
    "model", "models", "representation", "representations",
    "embodiment", "embodiments", "copy",
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ""
    token = prefix.token_strings[-1]
    value = 0.064 if token in {" instance", " instances"} else 0.0
    if token.strip() == "of":
        match = re.search(r"\b([A-Za-z]+)\s*$", tail)
        word = match.group(1) if match else ""
        if word == "instance":
            value = 0.77 if token[:1].isspace() else 0.52
        elif word == "instances":
            value = 0.64
        elif word in EXAMPLES:
            value = 0.29
        elif word in VERSIONS:
            value = 0.27
        elif word in REPRESENTATIONS:
            value = 0.15
    return (doc, (tail + token)[-40:]), value

programs.haiku:
"""Component layers.0.mlp.down_proj:4551 (layer 0 MLP down-projection) is an
"instance of" detector: it fires on the word " of" when the phrase is "instance of"
(as in knowledge-base style "X instance of Y" lines, or "is an instance of").

The rule, using only the previous word:
  * " of" right after " instance" -> about 0.77 (its typical value);
  * " of" right after " instances" -> about 0.63;
  * " of" right after a word for a particular example or kind of thing
    ("example of", "version of", "type of", "form of", ...) -> about 0.25;
  * any other " of" -> about 0.03 (barely above zero);
  * every other token -> 0.

Nothing is carried between positions. A new document starts with no previous
word, so the rule does not look across a document boundary.
"""

READS = ()

STRONG_AFTER = {" instance": 0.77, " instances": 0.63}

KIND_NOUNS = {
    " example", " examples", " version", " versions", " type", " types",
    " illustration", " variant", " copy", " copies", " form", " forms",
    " experience", " experiences", " embodiment", " embodiments",
    " definition", " application", " applications", " case", " moment",
    " moments", " incidents",
}
KIND_VALUE = 0.25
OTHER_OF_VALUE = 0.03


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    if len(tokens) < 2 or tokens[-1] != " of":
        return carry, 0.0
    if prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, OTHER_OF_VALUE
    before = tokens[-2]
    if before in STRONG_AFTER:
        return carry, STRONG_AFTER[before]
    if before in KIND_NOUNS:
        return carry, KIND_VALUE
    return carry, OTHER_OF_VALUE

programs.luna:
"""Predict a small bias for “of”, strongest in instance-of phrases.

In training text, “ of” is unusually activated after “instance”, as in
entity-type statements. Plural instances are similar; examples, versions, and
embodiments get a smaller prediction. Other “of” tokens get a tiny baseline.
"""
READS = ()

_EXAMPLE_VERSION = {
    "example", "examples", "version", "versions", "embodiment", "embodiments"
}


def step(carry, prefix, upstream):
    if len(prefix.token_strings) < 2:
        return None, 0.0
    if prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0

    current = prefix.token_strings[-1].strip().casefold()
    previous = prefix.token_strings[-2].strip().casefold()
    if current != "of":
        return None, 0.0
    if previous == "instance":
        return None, 0.776
    if previous == "instances":
        return None, 0.65
    if previous in _EXAMPLE_VERSION:
        return None, 0.28
    return None, 0.03

programs.sol:
"""A lexical signal for FOLLOW, and weaker sequence/pursuit associations.

FOLLOW and its inflections get large positive activations. Listing phrases
('the following', 'as follows') get smaller ones. The signal continues on
split suffixes and a few following articles/pronouns. Related order,
monitoring, compliance words and multilingual follow/next stems get weaker
responses. Everything else is zero: this is not a full semantic parser.
Stem matches may also fire in unrelated words with the same spelling.
Two preceding tokens are remembered, resetting at each document boundary.
"""
READS = ()

ORDER_AND_COMPLIANCE = set('after previous previously subsequent subsequently preceding '
            'thereafter accompanied accompany obey abide escort succeeded'.split())
MONITOR = set('watch watched watching track tracked repeat repeated repeats '
              'repeating trail trailing trace attend attended avoid avoiding'.split())
CONTINUE = set('continue continued continues continuing proceed proceeding '
               'sequence sequences consecutive post prev append below conclude '
               'concludes accordance pursuant practice nach'.split())
FOLLOW_STEMS = {'suiv', 'segu', 'seguir', 'siguiente', 'siguientes', 'seguint',
                '跟', '追', '循', '随', '隨', '随后', '随之', '跟踪', '追踪',
                '追逐', '跟进', '跟你', '跟他', '跟她', '遵守'}
COMPLIANCE = {'按照', '照', '依', '依法', '随着', '隨著', '追求'}


def lexical_value(word):
    if word == 'follow':
        return 8.4
    if word in {'following', 'follows', 'followed'}:
        return 7.2
    if word in {'follower', 'followers'}:
        return 5.3
    if word in {'遵循', '跟随', '追随'}:
        return 5.0
    if word == '跟着':
        return 4.1
    if word in FOLLOW_STEMS or word in {'fol', 'foll', 'след', 'ตาม', '追寻'}:
        return 2.5
    if word in {'pursue', 'pursuing', 'pursued', 'preced', 'preceded',
                'следует', 'послед'}:
        return 1.6
    if word == 'after':
        return 1.23
    if word in COMPLIANCE:
        return 1.1
    if word in ORDER_AND_COMPLIANCE or word in {'после', 'après', '从', '從', '如下', '以下'}:
        return 0.95
    if word in MONITOR or word == 'tracking':
        return 0.85
    return 0.56 if word in CONTINUE else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, before = carry[1:] if carry and carry[0] == doc else ('', '')
    raw = prefix.token_strings[-1]
    word = raw.strip().lstrip('_.-').lower()
    value = lexical_value(word)
    if previous == 'follow' and not raw[:1].isspace():
        if word in {'s', 'ed', 'ing', 'er', 'ers'}:
            value = 6.4 if word == 's' else 7.2
            word = 'follow' + word
        elif word == 'ings':
            value = 5.5
    elif previous == 'f' and word in {'ollow', 'ollower'}:
        value = 7.0 if word == 'ollow' else 5.6
    elif previous == 'ollow' and word in {'ing', 'ed', 's'}:
        value = 5.0
    elif previous == 'след' and word == 'ующ':
        value = 2.55
    elif previous == 'fol' and word in {'gende', 'genden', 'gend'}:
        value = 1.9
    if word == 'following' and previous == 'the':
        value = 2.1 if before in {'of', 'consider'} else 2.6
    elif word == 'follows' and previous == 'as':
        value = 2.7
    elif word == 'follow' and previous == 'the':
        value = 6.9
    elif previous in {'follow', 'following', 'follows', 'followed'}:
        if word in {'a', 'an', 'of', 'the'}:
            value = 2.15 if word == 'the' else 2.6
        elif word in {'this', 'it', 'me', 'us'}:
            value = 1.5
    return (doc, word, previous), float(value)

programs.haiku:
"""Component layers.0.mlp.down_proj:4552 is a "follow" detector.

It fires on the English verb "follow" in any form, on the word itself, just before its
object: "easy to follow", "followed by", "It follows that", "Following the signing of".
Its value is lower when "following" or "follows" introduces a list ("the following
steps", "as follows:"). It is weaker on "after", "previous", "subsequent" and "preceding"
and on verbs of following, complying and attending (obey, comply, pursue, heed, adhere,
track, watch, continue, attend, avoid), and weak on translations of "follow" (跟, 遵循,
按照, seguir). Everywhere else it stays near 0.
"""
READS = ()

VERB_FORMS = {"follow", "followed", "follows", "following"}
INTRODUCER_BEFORE = {"the", "as"}  # "the following ...", "as follows:"
SECONDARY = {"after", "previous", "previously", "subsequent", "subsequently", "preceding",
             "below", "obey", "comply", "pursue", "heed", "adhere", "track", "watch",
             "continue", "attend", "avoid"}
FOREIGN_FOLLOW = {"跟", "跟着", "遵循", "按照", "seguir", "siguiente", "siguientes", "从"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    before = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
