programs.sol:
"""A negative detector for word continuations after an en-like ending.

The main response follows Latin en (also accented e) or Cyrillic ен/ён.
It is largest for short fragments, weaker for longer fragments and
vowel-initial continuations, and usually absent across a space. Nearby
nasal spellings have smaller responses. These are spelling heuristics,
not a dictionary of words or a complete pronunciation model.
"""
READS = ()
EN_ENDINGS = ('en', 'én', 'ën', 'ен', 'ён')
KATAKANA_E_ROW = frozenset('エケセテネヘメレゲゼデベペ')


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    current = prefix.token_strings[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    ending = previous.lower()
    letters = current.isalpha()
    value = -0.003 if letters else -0.006

    if ending.endswith(EN_ENDINGS):
        if letters:
            before = max(0, min(8, len(previous.strip())) - 3)
            after = max(0, min(8, len(current)) - 2)
            response = (-1.16 + 0.21 * before + 0.15 * after
                        - 0.027 * before * after)
            if previous.istitle():
                response -= 0.26
            if current[0].lower() in 'aeiou':
                response += 0.22
            # A capitalized word is less like an unbroken continuation.
            if current.istitle() and not current.isupper():
                response += 0.31
            value += min(0.0, response)
        elif current.startswith(' '):
            value -= 0.013
        elif current.isdigit():
            value -= 0.26
        elif current.startswith(('-', '_')):
            value -= 0.29
        elif current.startswith(("'", '’')):
            value -= 0.16
    elif letters:
        if ending.endswith(('enn', 'енн')):
            value -= 0.51
        elif ending.endswith(('n', 'н', 'нь')):
            value -= 0.087
        if ending.endswith('eng'):
            value -= 0.34
        elif ending.endswith(('end', 'ent', 'ens', 'ern', 'ень')):
            value -= 0.085

    if letters and previous.endswith('ン'):
        value -= 0.10
        if len(previous) >= 2 and previous[-2] in KATAKANA_E_ROW:
            value -= 0.33
        if previous.endswith('エン'):
            value -= 0.37
    return (document, current), value

programs.haiku:
"""layers.0.mlp.down_proj:4555 -- a "-en fragment" detector.

This component goes negative on a word piece that continues a word the tokenizer split
apart, when the piece just before it is a short fragment ending in "en" (or Cyrillic "ен").
Examples: "En|edis", "Den|ham", "Ben|oit", "phen|anth|ren", "Spinomen|al", "феном|ен".
The model is partway through a rare word there and the component is strongly negative;
the shorter the continuing piece, the more negative (1-2 letters about -1.0, 4+ about -0.65).
Words that are complete on their own ("Screen", "open", "token") do not trigger it much.
A weaker negative (-0.08) is predicted on any other word piece that follows a fragment
ending in "n". Everything else is predicted as 0.

The program keeps no state: it reads only the newest token and the token before it,
and it treats the first token of each document as having no predecessor.
"""

READS = ()


def _is_word_piece(s):
    # a token that continues a word: no leading space, starts with a letter or digit
    return s[:1].isalnum() and not s.startswith(" ")


def _strong(piece):
    # the shorter the continuing piece, the more negative
    if len(piece) <= 2:
        return -1.05
    if len(piece) == 3:
        return -0.86
    return -0.65


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    if len(toks) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    if not _is_word_piece(cur):
        return None, 0.0
    prev = toks[-2].strip().lower()
    if prev.endswith("en") or prev.endswith("ен"):
        if len(prev) <= 5:
            return None, _strong(cur)
        return None, -0.2
    if prev.endswith("n"):
        return None, -0.08
    return None, 0.0

