"""A lexical markup/serialization signal, opposed to emphasis and focus.

XML names produce the largest positive values. Related format names,
'ml' fragments, document suffixes and opening angle brackets also respond.
Highlighting, focusing and emphasis words are negative. These are spelling
rules on the current token, not a parser or a claim about the whole text.
The --- separator and selected chat tags get small fixed values. All other
tokens get zero; no earlier tokens or document state are used.
"""
READS = ()

# Spellings/fragments of markup/data formats and words used in their APIs.
MARKUP_WORDS = {
    'xml': 6.4, 'xmlns': 5.6, 'yaml': 2.3, 'yml': 3.5,
    'aml': 3.2, 'qml': 2.9, 'fxml': 2.5, 'uml': 1.6,
    'html': 0.6, 'htm': 0.85, 'xhtml': 2.0,
    'svg': 1.35, 'rdf': 1.45, 'owl': 1.25,
    'xmlhttprequest': 1.0, 'xmlelement': 5.0,
    'xpath': 1.15, 'marshal': 0.9, 'createelement': 0.57,
}
DOCUMENT_SUFFIXES = {'md': 0.69, 'txt': 1.2, 'csv': 1.1, 'plist': 1.9}
HTML_TAGS = set('div p br a span h pre tr form th html body head img '
                'table title b i u button hr script input li nav'.split())


def lexical_value(token):
    stripped = token.strip()
    word = stripped.lstrip('./_(').lower()
    if word in MARKUP_WORDS:
        return MARKUP_WORDS[word]
    if stripped.startswith('.') and word in DOCUMENT_SUFFIXES:
        return DOCUMENT_SUFFIXES[word]
    if stripped == ',omitempty':  # Go's instruction to omit empty fields.
        return 1.2
    # The same letters occur as a unit, or as pieces of longer format names.
    if word == 'ml':
        if stripped.endswith('mL'):
            return 0.75
        if token.startswith(' '):
            return 1.75
        return 1.35 if stripped.startswith('/') else 3.5
    if word == 'мл':
        return 1.0
    if stripped == '---':
        return 0.78
    if stripped in ('<think>', '</think>'):
        return 0.32 if stripped == '<think>' else -0.30
    if stripped.startswith('<tool_'):
        return 0.12
    if token.startswith('<|'):
        return 0.0
    if '<' in stripped:
        if '<<' in stripped or '</' in stripped:
            return 0.04
        if any(s in stripped for s in ('<=', '<-', '<?', '<>')):
            return 0.26
        tail = stripped.split('<', 1)[1]
        if tail in HTML_TAGS:
            return 0.4
        if stripped.startswith('<') and (tail[:1].isalpha() or tail == "'"):
            return 1.03
        return 0.88 if stripped == '<' else (0.2 if '><' in stripped else 0.63)
    if word in ('＜', '⟨', 'langle'):
        return 0.65
    if word.startswith('highlight'):
        return -2.7 if token == 'highlight' else -1.8
    if word.startswith(('emphas', 'underscore', 'showcas')):
        return -1.0
    if word in ('focus', 'focused', 'focusing', 'focuses'):
        return -0.85
    if word in ('attention', 'concentration', 'concentrations'):
        return -0.5
    if word in ('强调', '強調', '重点', '重點', '关注', '關注'):
        return -1.0
    if word in ('突出', '发挥', '發揮'):
        return -1.6
    return 0.0


def step(carry, prefix, upstream):
    return None, float(lexical_value(prefix.token_strings[-1]))

