programs.sol:
"""Approximate document openings and Python method-signature activations.

Predict larger positives at document openings (using case, length, and a
few opening labels) and on Python receiver arguments, especially in an
__init__ declaration. Calls to __init__ receive a smaller positive. Most
other tokens are left near zero; a few code and formatting symbols have
small, consistent signed responses, as do a few English pronouns and
time adverbs. A '(this' argument in JavaScript is also positive. The state
keeps only a short text tail and resets at each new document.
"""
import re

READS = ()
QUESTION_STARTS = {'What', 'How'}
TIME_ADVERBS = {'ever', 'never', 'yet', 'already'}
PRONOUN_STARTS = {'This', 'We', 'You', 'She'}
METHOD = re.compile(r'\bdef\s+[\w_]+$')
DUNDER_METHOD = re.compile(r'\bdef\s+__\w+$')
CONSTRUCTOR = re.compile(r'\bdef\s+__init__\($')


def opening(s):
    if s == 'Title':
        return 1.88  # A document's title label.
    if s == 'package':
        return 0.88  # A source file's package declaration.
    if s == '<?':
        return 0.81  # PHP opening delimiter.
    if s in QUESTION_STARTS or s in PRONOUN_STARTS:
        return 0.67
    if s in {'Why', 'Where', 'Who'}:
        return 0.30
    if s == 'When':
        return 0.12
    if s in {'The', 'A', 'An'}:
        return 0.13
    if s in {'//', '/*'}:
        return 0.42
    if s == '//\n':
        return -0.75
    if s == '/*\n':
        return -0.32
    if s == '/*\r\n':
        return -0.93
    if s in {'##', '###'}:
        return 0.52
    if s == '#':
        return 0.20
    if s in {'import', 'class', 'def'}:
        return 0.20
    if s.strip(' \t(') in {'int', 'char'}:
        return -0.65
    if s.isascii() and s.isalpha() and s.istitle() and len(s) > 1:
        return 0.28 if len(s) <= 5 else 0.13
    if s.isascii() and s.isalpha() and s.islower() and len(s) > 1:
        return 0.045
    if not s.isascii() and s.isalpha() and s.istitle():
        return 0.16
    if s.startswith(' ') and s[1:].isalpha() and s[1:].istitle():
        return 0.06
    if s == r'\t':
        return -0.43
    if s.isspace():
        return -0.03
    if '�' in s:
        return 0.38
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    new = carry is None or carry[0] != doc
    tail = '' if new else carry[1]
    value = opening(s) if new else 0.0
    if not new:
        word = s.strip()
        if word.lower() in TIME_ADVERBS:
            value = -0.11
        elif word.lower() == 'she':
            value = 0.13 if word[0].isupper() else 0.06
        elif word.lower() == 'her':
            value = -0.047
        elif s == 'The':
            value = -0.047
        elif word == 'def':
            value = -0.065
        elif s == ' self':
            value = 0.068
        elif s == '(self':
            value = 0.48 if METHOD.search(tail) else 0.18
        elif s == 'self':
            if CONSTRUCTOR.search(tail):
                value = 1.30
            elif tail.endswith('__init__('):
                value = 0.80
            elif tail.endswith('__('):
                value = 0.42
            else:
                value = 0.04
        elif s == '__(':
            value = 0.78 if DUNDER_METHOD.search(tail) else 0.29
        elif s == '(this':
            value = 0.72 if tail.endswith('.call') else 0.11
        elif s == 'init':
            if tail.endswith(' __') and 'def ' in tail:
                value = 0.63
            elif tail.endswith('__'):
                value = 0.43
            else:
                value = 0.15
        elif s == '#include':
            value = -0.26
        elif word == 'void':
            value = -0.11 if s[0].isspace() else -0.26
        elif s == '<?':
            value = 0.24
        elif s == r'\t':
            value = -0.044
        elif s == '²':
            value = -0.078
        elif s == '\r':
            value = 0.20 if tail.endswith('\r') else 0.04
    return (doc, (tail + s)[-120:]), float(value)

