programs.sol:
"""Approximate responses to tightly joined fragments in structured text.

Short uppercase fragments following short lowercase fragments receive the
strongest generic response. Letter fragments following numbers receive a smaller
response, with adjustments for hexadecimal letters and ordinal endings. Local
rules cover hostname labels, key identifiers, LaTeX environments, MIME notation,
file suffixes, unusual separators, and an initial Q question label. Training
examples motivated these cues; weak, token-specific prose effects are omitted.
"""
import re
READS = ()
FILE_SUFFIXES = {
    '.py', '.js', '.rs', '.java', '.html', '.jar', '.md', '.yaml', '.yml',
}
IMAGE_HOSTS = {'.unsplash', '.imgur', '.githubusercontent'}
SOCIAL_HOSTS = {'.facebook', '.blogspot'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    initial = carry is None or carry[0] != doc
    previous, recent = ('', '') if initial else carry[1:]
    token = prefix.token_strings[-1]
    letter = token.isascii() and token.isalpha()
    prev_letter = previous.isascii() and previous.isalpha()
    number = previous.isascii() and previous.isdigit()
    value = 0.0
    if letter:
        if number:
            value = 0.24 if token.isupper() and len(token) <= 2 else 0.12
            if len(token) == 1 and token.lower() in 'abcdef':
                value = -0.05 if token == 'f' else 0.06
            elif token == 's':
                value = 0.03
            elif token in {'st', 'nd', 'rd', 'th'}:
                value = 0.07
        elif len(token) <= 2 and prev_letter:
            if token.isupper() and previous[-1].islower():
                value = 0.43 if len(previous) <= 2 else 0.10
            elif token.isupper() and len(previous) == 1:
                value = 0.18 if len(token) == 1 else 0.04
            elif token.istitle() and len(token) == 2:
                value = 0.25 if len(previous) <= 2 else 0.04
            elif token.islower() and len(previous) == 1:
                value = 0.10 if len(token) == 1 else 0.035
        elif token.isupper() and len(token) <= 2:
            value = 0.012
    if initial and token == 'Q':
        value = 0.382
    if token in FILE_SUFFIXES:
        value = -0.045
    host = re.search(r'(?:https?://|www)[^/\s"<>]*$', recent)
    if host and re.fullmatch(r'\.[a-z][a-z-]*', token):
        value = 0.16
        if token in {'.google', '.youtube'}:
            value = 0.95
        elif token in SOCIAL_HOSTS:
            value = 0.45
        elif token in IMAGE_HOSTS:
            value = 0.60
        elif token == '.io':
            value = 0.55
        elif token == '.org':
            value = 0.05
        elif token == '.gov':
            value = 0.32
        if previous == '.github' and token == '.io':
            value = 0.03
    if token == '.com' and previous.endswith('github'):
        value = 0.40 if previous == '.github' else -0.22
    if token == '_key':
        value = 0.08
        if previous.endswith('api'):
            value = 0.65
        elif previous.endswith(('public', 'private', 'access')):
            value = 0.32
    if token in {'matrix', 'array', 'atrix', 'agram'}:
        if re.search(r'\\(?:begin|end)\{[bp]?$', recent):
            value = 0.76 if token == 'matrix' else 0.28
        elif token == 'atrix' and recent.endswith('{pm'):
            value = 0.40
        elif token == 'agram' and recent.endswith('{di'):
            value = 0.45
    if previous in {'application', 'text', 'image'}:
        if token == '/vnd':
            value = 0.76
        elif token == '/xml':
            value = 0.30
    if token == '\r':
        value = -0.115
    elif token == '\u00a0':
        value = -0.045
    elif token and set(token) == {'·'}:
        value = -0.09
    return (doc, token, (recent + token)[-160:]), float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 4560: a small, diffuse feature whose clearest
signal is the preposition "of" (and "for", "in", "on", "to", ...) directly after a
capitalised word, as in names of institutions and places ("Institute of", "University of",
"Department of"). That "of" is strongly negative, most of all after an institution or place
noun; other prepositions after a capitalised word are mildly negative. A lowercase word right
after a capitalised word is weakly positive. Every other position is predicted as 0, the
component's typical near-zero value. This explains about 13% of its variance on eval."""
READS = ()
PREPS = {"of", "for", "in", "on", "to", "with", "from", "by", "at"}
FUNCTION_STARTS = {"The", "A", "An", "One", "Some", "Most", "None", "All", "Each", "Several", "Many", "This", "That", "These", "Those", "It", "In", "As", "And", "But", "If", "When", "What", "Which", "Who", "He", "She", "We", "They", "You", "I"}
INSTITUTIONS = {"Institute", "University", "School", "College", "Academy", "Department", "Ministry", "Museum", "Board", "Council", "Court", "Association", "Agency", "Republic", "City", "Valley", "State", "Party", "Bank", "Union", "Office", "Society", "Center", "Centre", "Conference", "Battle", "Law", "Treaty", "Secretary", "Director", "President"}

def step(carry, prefix, upstream):
    p = prefix.position
    if p == 0 or prefix.document_ids[p] != prefix.document_ids[p - 1]:
        return None, 0.0
    cur = prefix.token_strings[p]
    prev = prefix.token_strings[p - 1].strip()
    word = cur.strip()
    if word in PREPS and prev[:1].isupper() and prev not in FUNCTION_STARTS:
        if word == "of":
            return None, -0.9 if prev in INSTITUTIONS else -0.3
        return None, -0.15
    if prev[:1].isupper() and cur.startswith(" ") and word[:1].islower():
        return None, 0.05
    return None, 0.0

programs.sol:
"""A quotation-opening detector, strongest at the start of a line.

Whitespace, sentence punctuation, and code-like line syntax distinguish
quoted speech from literal delimiters or closing marks. Backticks and
line-initial list/table/blockquote markers have smaller negative responses.
The constants are approximate activation sizes fitted on training text.
"""
READS = ()


def response(token, previous, first, line):
    text = token.lstrip()
    p = previous.rstrip()
    spaced = token[:1].isspace()
    newline = previous.endswith('\n')
    sentence = p.endswith(('.', '!', '?'))
    colon = p.endswith((':', '：'))
    code = (line[:1].isspace() or any(c in line for c in '{}=;')
            or '\\n' in line or line.count('(') > line.count(')'))

    if text.endswith(('\n', '\r')):
        return -0.15 if text.startswith("'") else 0.0
    if text in {'：“', '。“', '，“', '、“'}:
        return -1.2
    if text.startswith('(') and text[1:] in {'"', '“', "'", '\\"'}:
        return -0.7 if spaced else -0.1
    if '\\' in text and text.replace('\\', '') in {'"', "'"}:
        return -0.75 if spaced else -0.38

    if text[:1] in {'"', "'", '“', '‘', '„', '«', '»'}:
        mark, tail = text[0], text[1:]
        single = mark in {"'", '‘'}
        curved = mark not in {'"', "'"}
        angle = mark in '«»'
        if tail and not tail[0].isalpha():
            return 0.0
        if mark == "'" and tail in {'s', 't', 'm', 're', 've', 'll', 'd'}:
            return 0.03
        if mark == "'" and tail and not (newline or first):
            return -0.2  # An apostrophe inside a word, not quoted speech.
        if first or newline:
            if spaced:
                return -1.7 if first else -3.5
            value = -3.0 if angle else (-3.6 if single else -4.8)
            if first:
                value *= 0.8
            if p.endswith((',', '(', '[', '{')):
                value += 2.0
            return value
        if previous and previous.isspace():
            return -0.9 if spaced else -1.6
        if not spaced:
            if tail:
                return -1.5
            latin_ending = p[-1:].isascii() and p[-1:].isalpha()
            if curved and not angle and not latin_ending:
                return -0.75
            return 0.17 if single else 0.25
        if mark == '»':
            return -0.3
        if p.endswith(('."', '.”', ".'", '!"', '?"')):
            return -3.2
        if ('"' in p or "'" in p) and p.endswith((':', ',')):
            return -0.4
        operators = {'=', '==', '===', '!=', '!==', '+', '<<'}
        if p.strip() in operators | {'echo', 'return', 'case'}:
            return 0.0
        if p.strip() in {'#', '•'}:
            return -3.0
        if sentence:
            if code and not curved:
                return -0.5
            if angle or mark == '„':
                return -2.0
            return -1.3 if single else -2.85
        if colon:
            if code and not curved:
                return -0.4
            return -1.2 if single else (-1.8 if angle else -2.3)
        if p.endswith(','):
            return -1.4 if curved else (-0.35 if single else -0.74)
        if code and not curved:
            return -0.25 if single else -0.6
        if angle:
            return -0.75
        return -1.25 if curved else (-0.5 if single else -1.0)

    if text in {'「', '『', '《', '〈'}:
        if text in {'《', '〈'}:
            return -1.5 if newline else -0.7
        return -3.1 if newline or first else (-1.9 if colon else -0.85)
    if text == '`':
        if newline or first:
            return -1.4
        return (-0.65 if colon or sentence else -0.38) if spaced else 0.05
    if text in {'*', '**', '>', '|'}:
        if spaced and text in {'*', '**', '|'}:
            return -0.3 if text == '**' else -0.05
        return -1.0 if newline or first else 0.02
    return 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    previous, line = ('', '') if first else carry[1:]
    value = response(token, previous, first, line)
    line = (line + token).rsplit('\n', 1)[-1][-300:]
    return (doc, token, line), float(value)

"""Periods are most negative in structured text rather than ordinary prose.

A punctuation form sets the baseline and sensitivity to text style. The
negative evidence is code marks, indentation, paths, colons, dotted names,
Han characters, recent line breaks and unspaced alphabetic pieces. Document
rates of word/number tokens contribute positively. Early positions and a
preceding East Asian or Thai token contribute negatively. Non-period tokens
receive a near-zero constant; incidental word-specific responses are omitted.
A few document-initial punctuation forms have separate, fixed baselines.
"""
from collections import Counter, deque
from math import sqrt

READS = ()

# With no earlier text, these punctuation forms have their own fixed response.
INITIAL_PUNCTUATION = {
    ".": -0.493,
    " .": -0.676,
    ".\n": 0.191,
    ".\n\n": 0.047,
    ").": -0.303,
    "。": -0.171,
}


def punctuation_form(s):
    """Return (baseline, text-style sensitivity), or None for non-periods."""
    if "." not in s:
        return (0.084, 0.091) if "。" in s else None
    t = s.strip()
    if t == ".":
        if s.startswith(" "):
            return -0.224, 1.198
        return (0.017, 0.731) if "\n" in s else (-0.085, 1.000)
    if t and all(c == "." for c in t):
        return 0.073, 0.200                 # ellipsis
    if t.startswith("."):
        tail = t[1:]
        if tail.isalpha():
            return (0.013, 0.480) if len(tail) == 1 else (0.064, 0.037)
        if tail in (",", '"', "'", ")"):
            return 0.151, 0.548
        return -0.066, 0.427               # dot plus other punctuation
    if t.endswith("."):
        lead = t[:-1]
        if "()" in lead:
            return -0.696, 0.364           # function-call ending
        if any(c in lead for c in "{}[]_"):
            return -0.162, 0.958
        if lead == ")":
            return 0.025, 0.946
        return -0.085, 0.887
    return -0.253, 0.064                   # dot embedded elsewhere


def east_asian_or_thai(s):
    return any("\u3040" <= c <= "\u30ff" or "\uac00" <= c <= "\ud7af"
               or "\u0e00" <= c <= "\u0e7f" or "\u4e00" <= c <= "\u9fff"
               for c in s)


def saturate(rate):
    """A few structural marks are informative; their effect then levels off."""
    return rate / (rate + 0.08)


def step(carry, prefix, upstream):
    s, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, Counter(), deque(), deque(), False)
    _, n, counts, breaks, unspaced_letters, previous_script = carry
    n += 1
    flags = {
        "word_or_number": ((s.startswith(" ") and s.strip().isalpha())
                           or s.isalpha() or s.strip().isdigit()),
        "code": any(c in s for c in "{}_"),
        "han": any("\u4e00" <= c <= "\u9fff" for c in s),
        "indent": "\t" in s or "  " in s,
        "slash": "/" in s,
        "colon": ":" in s,
        "dotted_name": s.lstrip().startswith(".") and any(c.isalpha() for c in s),
    }
    counts.update(flags)
    breaks.append("\n" in s)
    unspaced_letters.append(s.isalpha())
    if len(breaks) > 64:
        breaks.popleft()
    if len(unspaced_letters) > 16:
        unspaced_letters.popleft()
    carry = (doc, n, counts, breaks, unspaced_letters, east_asian_or_thai(s))
    if n == 1 and s in INITIAL_PUNCTUATION:
        return carry, INITIAL_PUNCTUATION[s]
    form = punctuation_form(s)
    if form is None:
        return carry, -0.001
    rate = {name: counts[name] / n for name in flags}
    style = -0.632 / sqrt(n) + 0.261 * rate["word_or_number"]
    style -= 0.471 * saturate(rate["code"]) + 1.402 * sqrt(rate["han"])
    style -= 0.588 * saturate(rate["indent"]) + 0.464 * saturate(rate["slash"])
    style -= 0.327 * saturate(sum(breaks) / len(breaks))
    style -= 0.295 * sum(unspaced_letters) / len(unspaced_letters)
    style -= 0.463 * saturate(rate["colon"]) + 0.695 * previous_script
    style -= 0.627 * sqrt(rate["dotted_name"])
    baseline, sensitivity = form
    return carry, float(baseline + sensitivity * style)

"""A spelling-based detector of East Asian grammatical linking particles.

Chinese 的, Japanese の and Korean 의 give strong negative responses;
object markers を and 을/를, Chinese 之 and Japanese な give smaller ones.
Responses weaken when a particle shares a token with a word or whitespace,
and at the start of a document. Merged Chinese possessive pronouns are
weaker still. All other tokens receive zero. No syntactic parsing is done.
"""
READS = ()

PARTICLES = {
    '的': -5.29, 'の': -2.35, '의': -2.93, '之': -0.89,
    'を': -1.38, '을': -1.58, '를': -1.58, 'な': -1.02,
}
SPACED = {'的': -3.91, 'の': -1.87, '의': -0.78, 'を': -1.16}
PERSON_PRONOUNS = {'我', '你', '您', '他', '她', '它', '自己'}
QUOTES = set('“”‘’\"\'')


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip()
    value = 0.0
    if word in PARTICLES:
        value = PARTICLES[word] if raw == word else SPACED.get(word, 0.0)
        if (prefix.position == 0 or
                prefix.document_ids[-1] != prefix.document_ids[-2]):
            value *= 0.58
    elif word.endswith('的'):
        stem = word[:-1]
        if stem and all(c in QUOTES for c in stem):
            value = -3.2
        elif stem.removesuffix('们') in PERSON_PRONOUNS:
            value = -0.3
        else:
            value = -0.6
    elif word.startswith('的'):
        rest = word[1:]
        if rest == '一':  # The particle followed by "one".
            value = -3.14
        elif rest == 'な':  # Japanese adjectival ending 的な.
            value = -1.0
        elif len(rest) == 1 and '\u4e00' <= rest <= '\u9fff':
            value = -1.2
        elif len(rest) == 2 and rest.startswith(('一', '第')):
            value = -0.75
    elif word.endswith(('を', '을', '를')):
        value = -0.58
    elif word.startswith('を'):
        value = -0.25
    return None, float(value)

programs.luna:
"""Approximate a few East Asian grammatical particles at their token."""

READS = ()

# Typical negative contributions for particles seen repeatedly in high-impact
# examples: Chinese 的, Japanese の and を, and Korean 을.
PARTICLE_ACTIVATION = {
    "的": -5.4,
    "の": -2.4,
    "を": -1.3,
    "을": -1.6,
}


def step(carry, prefix, upstream):
