programs.sol:
"""A token-spelling approximation to a col- feature and a wide-blank feature.

Col/coll fragments, collection, collecting, and college fire strongly;
color and other col- families fire less. There are also responses to some
Chinese collecting/color/cold words, and independently to the literal
glyphs 却/卻 and 冒. Wide blank tokens peak around thirty columns. A small
one-token memory covers split suffixes and 'collection of'/'college of'.
This is not a test of the topic or meaning of the whole passage.
"""
import string

READS = ()

# Named word families and common spelling fragments, not token IDs.
COLLECTING = {'收藏', '收取', '集体'}
COLOR_OR_GATHERING = {'颜色', '顏色', '彩色', '采集', '搜集'}
SHORT_CHINESE_FORMS = {
    '色', '集', '科', '收', '藏', '颜', '顏', '集合', '回收',
}


def word(token):
    return token.lstrip(' \t' + string.punctuation).lower()


def lexical(token):
    w = word(token)
    if w in ('col', 'coll'):
        return 3.5
    if w.startswith('collection'):
        if w not in ('collection', 'collections'):
            return 2.0
        value = 3.4 if w.endswith('s') else 3.8
        return value + (0.9 if token == 'Collection' else 0.0) - (
            0.7 if token.startswith('.') else 0.0)
    if w.startswith('collect'):
        if w.startswith('collectiv'):
            return 1.6
        if w.startswith('collector'):
            return 2.2
        return 3.05
    if w.startswith('college'):
        return 2.8 if w.endswith('s') else 3.45
    if w.startswith('colleg'):
        return 1.6
    if w.startswith(('color', 'colour')) or w == 'couleur':
        return 0.5 if w.endswith(('ful', 'fully', 'ing')) else 1.5
    if w.startswith(('column', 'cold', 'collab', 'colab', 'collaps', 'coloc')):
        return 0.65
    if w.startswith('col'):
        return 1.5
    if 'collection' in w or w.startswith('ollect'):
        return 2.3
    if 'color' in w:
        return 0.9
    if w.startswith('кол'):
        return 2.7 if w in ('кол', 'колл') else 0.7
    if w in ('kol', 'kole'):
        return 1.8 if token.startswith(' ') else 1.1
    if w in ('ocol', 'icol'):
        return 1.7
    if w in ('oll', 'olor') or w.startswith(('cool', 'цвет')):
        return 0.8
    if w in ('ola', 'ols', 'ol'):
        return 0.25
    if w.startswith('gather'):
        return 0.48
    if w == '收集':
        return 3.1
    if w in COLLECTING:
        return 1.9
    if w in COLOR_OR_GATHERING:
        return 1.25
    if w in SHORT_CHINESE_FORMS:
        return 0.75
    if w.startswith(('冷', '凉')):
        return 0.9
    if w in ('却', '卻'):
        return 1.2
    if w in ('冒', '冒着'):
        return 2.9
    return 0.0


def blanks(token):
    horizontal = token.rstrip('\r\n')
    width = len(horizontal.expandtabs(4))
    tabs = horizontal.count('\t')
    if width <= 7:
        value = 0.0
    elif width <= 16:
        value = 0.1 if tabs >= 4 else (-0.1 if width > 11 or not tabs else 0.0)
    else:
        value = min(1.17, max(0.0, 0.12 * (width - 18)))
        if width <= 36 and tabs:
            value += 0.2 if tabs >= 4 or width >= 28 else 0.0
        if width > 36:
            value = max(0.8, 1.17 - 0.014 * (width - 36))
    return value * (0.7 if horizontal != token else 1.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    horizontal = token.rstrip('\r\n')
    if horizontal and not horizontal.strip(' \t'):
        value = blanks(token)
    else:
        value = lexical(token)
    if value == 0.0:
        if token.lower().strip() == 'of':
            value = 1.1 if previous.startswith('collection') else (
                0.3 if previous.startswith('college') else 0.0)
        elif token and token[0].isalpha():
            suffix = token.lower()
            if previous == 'collect' and suffix in ('ing', 's'):
                value = 2.15
            elif previous == 'col' and suffix.startswith(('lect', 'lege', 'on')):
                value = 2.0
            elif previous in ('col', 'coll', 'кол'):
                value = 0.7
    return (doc, word(token)), float(value)

programs.luna:
"""Recognize col- words and unusually wide whitespace tokens.

Words such as collection, college and color are the clearest lexical cases;
long whitespace tokens, often used for indentation, get a smaller response.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().casefold()

    if len(token) >= 20 and not token.strip():
        return None, 0.85
    if "кол" in word:
        return None, 2.6
    if word.startswith("coll"):
        return None, 3.7
    if word.startswith("col"):
        return None, 1.3
    return None, 0.0

programs.sol:
"""Predict selected split abbreviations and technical expressions.

The current token receives a large positive value when it completes a familiar
single-letter scientific or programming prefix (X-ray, P-value, C#, t.Run,
n_estimators, and so on). Spelling and capitalization matter. Slash-written
gender alternatives also get a positive value. Unrecognized tokens get zero;
this does not reproduce the component's many small activations elsewhere.
Only the immediately preceding token is kept, and documents reset that state.
"""
READS = ()


def completion(previous, token):
    """Scientific notation, units, software names, and programming idioms."""
    if previous in {'X', 'x'} and token in {'-ray', '-rays', '-Ray'}:
        value = 0.42 if previous == 'X' else 0.31
        if token == '-rays':
            value -= 0.11
        elif token == '-Ray':
            value += 0.11
        return value
    if token.startswith('-terminal'):
        if previous == 'N':
            return 0.50
        if previous == 'C':
            return 0.33
    if previous.lower() == 'p' and token in {'-value', '-values'}:
        return 0.40
    if previous == 't' and token in {'-test', '-tests'}:
        return 0.28 if token == '-test' else 0.34
    if token.startswith('-inter') and previous in {'x', 'y', 'Y'}:
        return 0.19 if previous == 'x' else 0.42
    if previous == 'z' and token == '-score':
        return 0.27
    if previous == 'C' and token == '#':
        return 0.31
    if previous == 'O':
        if token == '(Log':
            return 0.54
        if token == '(log':
            return 0.12
        if token in {'_CREAT', '_WRONLY'}:
            return 0.55
        if token in {'_RDONLY', '_DIRECTORY'}:
            return 0.38
        if token == '_TRUNC':
            return 0.20
    # Go test receivers followed by test/reporting methods.
    if previous == 't':
        if token in {'.Run', '.Errorf'}:
            return 0.40
        if token in {'.Error', '.Fatal'}:
            return 0.36
        if token == '.Fatalf':
            return 0.22
        if token in {'.Log', '.Logf'}:
            return 0.19
    # Conventional initial-letter abbreviations.
    if previous == 'c' and token == '/o':  # care of / complains of
        return 0.47
    if token == '&D' and previous in {'D', 'R'}:
        return 0.45 if previous == 'D' else 0.30
    if previous == 'S' and token == '&P':
        return 0.35
    if previous == 'U' and token in {'.S', '.K'}:
        return 0.06 if token == '.S' else 0.13
    if previous == 'N' and token == '/A':
        return 0.18
    # Predicted and observed response variables in machine-learning code.
    if previous == 'y' and token in {'_pred', '_true', '_correct'}:
        return 0.28
    # Biological abbreviations and chemical notation.
    if (previous, token) in {('S', 'ARS'), ('c', 'DNA'), ('c', 'AMP'),
                            ('m', 'TOR')}:
        return 0.29
    if previous == 'H' and token == 'Cl':
        return 0.22
    if previous == 'U' and token == '+':  # Unicode code-point notation
        return 0.20
    if previous == 'g':
        if token in {'/cm', '/mL'}:
            return 0.24
        if token == '/ml':
            return 0.16
        if token == '/mol':
            return 0.09
    if previous == 'm' and token in {'/s', '/z'}:
        return 0.10 if token == '/s' else 0.26
    # Software names and operations that split after their first letter.
    if previous == 'v' and token == 'Bulletin':
        return 0.66
    if previous == 'V' and token == 'LOOK':
        return 0.57
    if previous == 'n' and token == '_estimators':
        return 0.49
    if previous == 'D' and token == 'atalog':
        return 0.51
    if previous in {'y', '.y'} and token == 'andex':
        return 0.57
    return None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    previous = previous.strip()
    carry = (doc, token)
    value = completion(previous, token)
    if value is not None:
        return carry, value
    if (previous.lower(), token.lower()) in {('his', '/her'), ('he', '/she')}:
        return carry, 0.32
    return carry, 0.0

