"""Recognize digits immediately after a period and a short digit-run tail.

The strong response is common on fractional digits, but the same character
pattern also occurs in dotted version numbers and section labels.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    same_doc = carry is not None and carry[0] == doc
    previous_char = carry[1] if same_doc else ""
    fractional_digits = carry[2] if same_doc else 0

    value = 0.0
    count_before = 0
    starts_fraction = bool(token and token[0].isdecimal())
    continues_fraction = previous_char.isdecimal() and fractional_digits > 0
    if starts_fraction:
        if previous_char == ".":
            value = 1.64
        elif continues_fraction:
            if fractional_digits == 1:
                value = 0.18
            elif fractional_digits == 2:
                value = 0.055
            count_before = fractional_digits

    if token.isdecimal() and (previous_char == "." or continues_fraction):
        fractional_digits = count_before + len(token)
    else:
        fractional_digits = 0

    last_char = token[-1] if token else previous_char
    return (doc, last_char, fractional_digits), float(value)

