def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip()
    value = 0.0

    # Test outcomes and the word 'pass', also outside test logs.
    if word == 'PASS':
        value = -0.31 if token.startswith(' ') else -0.24
        if recent.endswith('---'):
            value = -0.83 if recent.endswith(' ---') else -0.67
    elif word == 'FAIL':
        value = -0.08
        if recent.endswith('---'):
            value = -0.49 if recent.endswith(' ---') else -0.40
    elif word in {'pass', 'Pass'}:
        value = -0.15
    elif word in {'passed', 'passing'}:
        value = -0.13

    # Installed dependencies and source-tree locations.
    elif token == '-packages' and recent.endswith('site'):
        value = -0.76 if '/' in recent else -0.55
    elif token == '-packages' and recent.endswith('/dist'):
        value = -0.51
    elif token == '_modules' and recent.endswith('node'):
        value = -0.09 if recent.endswith('/node') else -0.15
    elif token == '/repository':
        value = -0.39
    elif token == 'workspace':
        value = -0.08
    elif token in {'/workspace', '/src', '/tests'}:
        value = -0.05

    # Logging and formatted-output routines, distinguished by receiver.
    elif token == '.log' and recent.endswith('console'):
        value = -0.19
    elif token == '.Sprintf' and recent.endswith('fmt'):
        value = -0.39
    elif token == '.Printf' and recent.endswith('fmt'):
        value = 0.21
    elif token == '.Println' and recent.endswith('fmt'):
        value = -0.11
    elif token == '.println' and recent.endswith('out'):
        value = -0.13

    # Recognizable API/header expressions, not arbitrary token numbers.
    elif token == '.Scanner' and recent.endswith('util'):
        value = -0.79
    elif token == 'AnimationFrame' and recent.endswith('request'):
        value = -0.82
    elif token == '.createSequentialGroup':
        value = -0.79
    elif token == '/stdc' and recent.endswith('bits'):
        value = -0.67

