    'city': 1.17, 'cities': 1.19, 'urban': 1.35,
    '京': 1.39, '城': 0.77, '京都': 1.02, '成都': 1.4,
    '首都': 2.85, '都市': 4.61, '都市报': 0.8, '成都市': 1.7,
