"""A local spelling link after L: consonant continuations are usually positive,
vowel continuations usually negative (el + gan versus ol + ingu). Short pieces
carry the largest signal. Length, capitalization, and a vowel before L adjust
its strength. Weaker links follow L plus one character, or Japanese ru.
Document boundaries reset the remembered token.
"""
import unicodedata
from functools import lru_cache

READS = ()
L_LETTERS = set('lлλلלลłलলலలലლլ')
VOWELS = set('aeiouyаеёиоуыэюяαεηιουωاويىی')
OBSTRUENTS_AND_NASALS = set('bcdfghkmnpqstvzхбвгджзкмнпстфцчшщ')


@lru_cache(maxsize=65536)
def plain(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text.lower())
                   if not unicodedata.combining(c))


@lru_cache(maxsize=65536)
def ending_strength(token):
    s = plain(token).strip()
    if not s:
        return 0.0
    if s[-1] in L_LETTERS:
        n = len(s)
        strength = (0.93, 0.83, 0.73, 0.38, -0.08)[min(n, 5) - 1]
        if n > 1 and s[-2] in VOWELS:
            strength += 0.57
        if token.strip().istitle() or token.strip().isupper():
            strength += 0.12
        return max(0.0, strength)
    if len(s) > 1 and s[-2] in L_LETTERS:
        if s[-1] in 'ьъ':
            return 0.33
        return 0.11 if s[-1] in VOWELS else 0.09
    return 0.25 if s[-1] in 'るル' else 0.0


@lru_cache(maxsize=65536)
def continuation(token):
    s = plain(token)
    if not s:
        return 0.0
    c = s[0]
    if token[0].isspace():
        return 0.05
    if c in L_LETTERS:
        return -0.05
    sign = -1 if c in VOWELS else 1
    if c in 'iыиy':
        value = -0.55
    elif c in 'oою':
        value = -0.38
    elif c in VOWELS:
        value = -0.25
    elif c in 'rрρwj':
        value = 0.73
    elif c in OBSTRUENTS_AND_NASALS:
        value = 1.1
    else:
        return 0.13 if c.isalpha() else 0.07
    value += sign * (0.32 if len(token) == 1 else
                     0.14 if len(token) == 2 else 0.0)
    if token[0].isupper():
        value -= sign * 0.29
    if len(token) >= 5:
        value -= sign * 0.20
    if len(token) >= 7:
        value -= sign * 0.16
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = ending_strength(previous) * continuation(token)
    return (doc, token), float(value)

"""Approximate the component's strongest lexical responses.

Unusual Q letter-pairs, quant- and quarter- words are negative; 'why not'
is positive. Smaller rules cover English 'not' constructions, negative
assessments, and explicit thought/tool delimiters. Magnitudes were estimated from training rows.
This deliberately omits the component's diffuse, small lexical responses.
"""
READS = ()

# Short Q pairs differ in strength; QL is a relatively weak exception.
Q_PAIRS = {
    'qa': -1.70, 'qe': -1.45, 'qt': -1.35, 'qw': -1.45,
    'ql': -0.30, 'qi': -0.84,
}
TOOL_TAGS = {
    '<tool_call>': 0.084, '</tool_call>': -0.099,
    '<tool_response>': -0.031, '</tool_response>': 0.021,
}


def q_response(text):
    word = text.lstrip(' \t\n_./([,-')
    low = word.lower()
    spaced = text[:1].isspace()
    if low == 'q':
        return -0.13 if spaced or word == 'q' else -0.06
    if low == 'pyqt':
        return -1.80
    if low.startswith('q') and len(low) > 1 and low[1] != 'u':
        if len(low) == 2 and low.isalpha():
            if low == 'qs' and word.islower():
                return -0.84
            return Q_PAIRS.get(low, -1.10)
        return -0.08 if low == 'qrt' else -0.50
    if low.startswith('quant'):
        if low == 'quant':
            if word[0].isupper():
                return -0.69 if spaced else -0.52
            return -0.48 if spaced else -0.40
        if low == 'quantum':
            return -0.32 if word[0].isupper() else -0.45
        return -0.69 if low.startswith('quantitat') else -0.20
    if low.startswith('quarter'):
        if low == 'quarter':
            return -0.72 if spaced else -0.51
        if low.startswith('quarterback'):
            return -0.58
        return -0.54 if low == 'quarterly' else -0.35
    # Chinese quantity / calendar quarter and QR-code words.
    if '季度' in text or text == '数量':
        return -0.47
    if text == '二维码':
        return -0.80
    return None


