    word = previous.strip().lower().replace('’', "'")
    if word == 'why':
        return 0.87
    if word in {'am', "'m"}:
        return -0.10
    if word in {'have', 'has', 'had'}:
        return 0.24
    if word in {'can', 'could', 'may', 'might'}:
        return 0.20
    if word in {'is', 'are', 'were', "'s", "'re"}:
