            value = -0.12
        elif text.strip().lower() in {'wrong', 'impossible', 'unable'}:
            value = -0.15
        elif text.startswith(' ') and text.strip().lower() in {
            'cannot', 'never', 'non', 'nor', 'invalid', 'incorrect',
            'empty', 'undefined',
