programs.sol:
"""Lexical article/publishing detector, including some spelling spillover.

Whole 'article' words receive a large positive value; translations and
'particle' receive smaller ones. Article-like endings and publishing terms
receive weaker values. A few short metadata phrases are recognized too.
Case and identifier/path punctuation modify the article response. There is
also a small fixed response at </think>. Unlisted tokens predict zero.
State remembers only the current word fragment and document position.
English article responses are slightly stronger near the document start.
This is not a general topic classifier.
"""
import math
import re

READS = ()

# Related vocabulary, grouped by meaning rather than token identity.
GROUPS = (
    (5.0, {'文章', '篇文章', '的文章', '一篇文章'}),  # Chinese: article
    (3.8, {'这篇文章', '這篇文章'}),                 # this article
    (3.0, {'篇', '一篇', '这篇', '下一篇'}),        # article counter
    (2.7, {'本文', '記事'}),                      # this text / article
    (2.3, {'转载'}),                              # reprint
    (3.2, {'artikel', 'artykuł'}),                 # German/Polish article
    (4.0, {'artículo', 'artículos', 'artigo'}),      # Spanish/Portuguese
    (2.0, {'стать'}),                             # Russian article stem
    (1.3, {'小编', '责任编辑', '发表', '發表', '報導', '报道'}),
    (0.85, {'文', '内容', '章', '章节', '载', '載', '作者', 'автор', 'части'}),
    (0.7, {'autor', 'auteur', 'bài', 'ブログ'}),    # author / text / blog
    (1.1, {'paper', 'subsection', 'editorial'}),
    (0.9, {'content', 'blog', 'blogs', 'blogging', 'manuscript'}),
    (0.75, {'papers', 'section'}),
    (0.65, {'sections', 'abstract', 'tutorial'}),
    (0.55, {'references', 'excerpt', 'chapter', 'chapters', 'doi'}),
    (0.45, {'post', 'posted', 'contents'}),
    (0.8, {'posts'}),
    (0.37, {'publication', 'publications', 'publish', 'publishing',
            'publisher', 'paragraph', 'essay', 'piece', 'title'}),
    (1.4, {'artic'}), (0.6, {'partic'}),
    (0.47, {'</think>'}),
)
LEXICON = {word: value for value, words in GROUPS for word in words}


def response(token, previous):
    text = token.strip()
    word = text.lstrip("/._-('")
    lower = word.lower()
    if lower in {'article', 'articles'}:
        plural = lower.endswith('s')
        if token == text == word and previous.lower().endswith('p'):
            return 3.5 if plural else 3.25  # split 'particle(s)'
        if text.startswith("'"):
            return 3.2
        if text.startswith('/'):
            return 7.0 if plural else 5.6
        if text.startswith(('.', '_')):
            return 4.3
        if word[0].isupper():
            return 6.0 if plural else (5.7 if token != text else 5.2)
        return 5.1 if plural else (6.15 if token != text else 5.8)
    if lower in {'particle', 'particles'}:
        return 1.95 if lower.endswith('s') else 2.1
    if lower in {'icle', 'icles'}:
        if (previous + text).lower().endswith(('chronicle', 'chronicles')):
            return 0.4
        return 4.8 if text.isupper() else (2.35 if lower.endswith('s') else 1.55)
    # Endings shared with article words in Romance languages and German.
    if lower in {'ículo', 'ículos', 'iculo', 'iculos', 'igo', 'igos', 'olo', 'ikel'}:
        joined = (previous + text).lower()
        if joined.endswith(('artigo', 'artigos')):
            return 5.1
        if joined.endswith(('artículo', 'artículos', 'articolo', 'artikel')):
            return 3.4
        return 0.3 if lower == 'olo' else 1.0
    if lower in {'author', 'authors'}:
        return 1.05 if lower.endswith('s') or word[0].isupper() else 1.3
    if lower == 'published':
        return 1.15 if word[0].isupper() else 0.86
    if lower == 'editor':
        if text.startswith('/'):
            return 1.4
        return 0.7 if text.startswith(('_', '-')) else 0.45
    if word == 'قال':  # Arabic article fragment, also the word 'said'
        return 2.1 if previous.endswith('م') else 1.4
    if (lower == 'of'
            and previous in {'article', 'Article', 'articles', 'Articles'}):
        if previous[0].isupper():
            return 3.7
        return 2.1 if previous.endswith('s') else 2.9
    if (previous.lower() in {'article', 'articles'}
            and token.startswith(' ') and lower in {'for', 'on', 'by', 'in', 'about'}):
        return {'for': 0.8, 'on': 0.75, 'by': 0.75,
                'in': 0.35, 'about': 0.35}[lower]
    if lower == 'of':
        return {'author': 0.65, 'authors': 0.55, 'paper': 0.5,
                'content': 0.23, 'section': 0.2}.get(previous.lower(), 0.0)
    if lower == 'links' and previous.lower() == 'external':
        return 0.85
    return LEXICON.get(lower, 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same_doc = carry is not None and carry[0] == doc
    previous, position = (carry[1], carry[2] + 1) if same_doc else ('', 0)
    token = prefix.token_strings[-1]
    value = response(token, previous)
    if token.strip().lower() in {'article', 'articles'} and value > 4.0:
        value *= 0.98 + 0.1 * math.exp(-position / 50.0)
    tail = re.search(r'\w+$', previous + token)
    fragment = tail.group()[-32:] if tail else ''
    return (doc, fragment, position), float(value)

"""Approximate a predominantly negative response to IO/io spellings.

Short io fragments, bio and ratio are strongest; longer endings are weaker.
Case, accents and a few Latin-style endings distinguish their strengths.
Smaller branches cover media words, related vowel pairs, several non-Latin
spellings, and tool-call markup. Everything else receives 0.001.

Only the current token is used. In particular, common -ion endings do not
trigger the io-prefix rule. This captures the main spelling preference but
omits the component's finer token-specific and surrounding-word variation.
"""
import unicodedata

READS = ()

MEDIA = {
    'audio': -2.0, 'radio': -2.0, 'video': -1.25, 'videos': -0.95,
    'studio': -1.2, 'stereo': -1.1,
    '视频': -0.88, '音频': -1.25, 'видео': -1.8,
}
LATIN_ENDINGS = {'ius': -1.28, 'ium': -0.79, 'ious': -1.22,
                 'iously': -0.82, 'iu': -0.70, 'ario': -1.85}
VOWEL_PAIRS = {'jo': -0.95, 'yo': -1.15, 'eo': -1.1,
               'ao': -0.55, 'uo': -0.6}


def activation(token):
    if token == '<tool_call>':
        return -0.705
    word = token.strip().lstrip('._-/(:<,')
    low = word.lower()
    plain = ''.join(c for c in unicodedata.normalize('NFD', low)
                    if not unicodedata.combining(c))
    if low in MEDIA:
        return MEDIA[low]
    if word in {'io', 'IO'}:
        if token.startswith(('.', '/')):
            return -4.5
        return -4.45 if word == 'IO' else -3.8
    if word == 'Io':
        return -1.5
    if low in {'ratio', 'ratios'}:
        return -4.15 if low == 'ratio' else -3.3
    if low in {'bio', 'aio'}:
        return -4.55
    if low == 'rio':
        return -4.1 if word[0].isupper() else -2.9
    if low.startswith('bio'):
        return -1.85 if low == 'bios' else -0.65
    if low in LATIN_ENDINGS:
        return LATIN_ENDINGS[low]
    if low.startswith('io') and not low.startswith('ion'):
        if low == 'ios':
            return -2.25
        if low.startswith(('ioexception', 'ioerror')):
            return -0.4 if token.startswith('.') else -2.9
        return -0.8
    if plain.endswith('io'):
        if low != plain:
            if low[-1] != 'o':  # Final-vowel stress, as in Spanish -ió.
                return -0.35
            return -1.7 if len(plain) == 2 else -1.1
        if low in {'stdio', 'gpio'}:
            return -1.4
        if low == 'ohio':
            return -0.42
        if low in {'atio', 'asio'}:
            return -5.0
        n = len(low)
        if n <= 4:
            return -1.5 if low.startswith(('ch', 'iz')) else -2.75
        if n == 5:
            return -2.3 if low.endswith('ario') else -0.9
        return -0.25
    if plain.endswith('ios') and len(plain) <= 5:
        return -1.0
    if plain in VOWEL_PAIRS:
        return VOWEL_PAIRS[plain]
    if plain == 'geo':
        return -2.1
    if plain in {'neo', 'seo', 'joe', 'joi'}:
        return -0.7
    if low in {'オ', '오'}:
        return -0.95
    if low in {'يو', 'ジョ'}:
        return -2.1
    return 0.001


def step(carry, prefix, upstream):
    return None, float(activation(prefix.token_strings[-1]))

