"""Layer-0 MLP neuron 4585 (down_proj): a token-level detector for the vowel pair "io"
read as two separate vowels, as in "bio", "ratio", "radio", "video", "audio", "studio",
"IO", "Rio", "Mario". When the token carries that "io" it pushes the activation negative;
otherwise it stays near zero.

Strength depends on how much of the token is the "io" syllable:
  - the token is just "io" (any case or punctuation: "io", " IO", ".io", "/io"), or a short
    "-io" word piece like "bio", "ratio", "Rio", "ios": about -4;
  - a longer piece ending in "io" ("radio", "audio", "video", "studio", "Mario"): about -1.5;
  - "io" inside a longer piece, not followed by n, u, r or d: about -0.5.
English "-ion", "-tion", "-ious", "-ior", "-iod" words ("function", "information",
"various", "senior", "period") are left at zero, as the component ignores them.

The rule reads only the newest token, so it needs no carry between positions.
"""

import re

READS = ()

EXACT = {"io", "bio", "ratio", "ratios", "rio", "ios", "atio", "bios"}


def step(carry, prefix, upstream):
    letters = re.sub(r"[^a-z]", "", prefix.token_strings[-1].lower())
    if letters in EXACT:
        value = -4.0
    elif re.search(r"(io|video|audio|radio)$", letters):
        value = -1.5
    elif re.search(r"io[^nurd]", letters):
        value = -0.5
    else:
        value = 0.0
    return None, float(value)

