"""Approximate a positive detector of syllabic-L spellings, not all letter Ls.

Short -cle/-gle/-dle/-tle/-ple chunks are strongest. Longer words and
inflections usually weaken them; -able/-ible and common lexical exceptions
need lower values. Capitalized words and split-off syllables can be stronger.
Bare le/les/led/ling use the preceding letter, resetting between documents.
A weak echo survives onto 'of'. Small additional cues cover family/belly/
valley, Chinese classifiers, apples, and Japanese/Korean L-ending syllables.
These rules leave most other tokens at zero; they are not a full predictor
of the component's weaker, sometimes negative, background responses.
"""
import re

READS = ()
STOPS = frozenset('bcdgkpt')
ENDING = re.compile(r'([bcdfgkmnpstz]l)(e|es|ed|ing)$')
FAMILY = {'cl': 2.7, 'kl': 2.3, 'gl': 2.7, 'dl': 2.5,
          'tl': 2.3, 'pl': 2.6, 'bl': 2.0, 'fl': 1.2,
          'sl': 1.5, 'zl': 1.5}
WEAK = frozenset(('people', 'example', 'sample', 'principle', 'table',
                  'variable', 'vehicle', 'title', 'google', 'obstacle',
                  'oracle', 'recycle', 'entitle'))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    previous_letter = '' if reset else carry[1]
    previous_value = 0.0 if reset else carry[2]
    token = prefix.token_strings[-1]
    match = re.search(r'[A-Za-z]+$', token)
    text = match.group() if match else ''
    attached = text == token
    last_letter = (text[-1:] or previous_letter) if attached else text[-1:]
    low = text.lower()
    value = 0.0
    ending = ENDING.search(low)
    if ending:
        root = low[:ending.start(2)] + 'e'
        value = FAMILY.get(ending.group(1), 1.2)
        value *= max(0.2, 1 - 0.16 * max(0, len(root) - 6))
        if root.endswith('able'):
            value = 0.7 if len(root) <= 5 else 0.12
        if root.endswith('ible'):
            value = 1.4 if len(root) <= 5 else 0.12
        if root in ('single', 'simple', 'double', 'little', 'multiple'):
            value = 0.9
        if root in ('middle', 'couple', 'article', 'particle', 'muscle'):
            value = 1.15
        if root in ('trouble', 'soluble', 'purple', 'rifle', 'eagle'):
            value = 0.65
        if root.endswith('ucle'):
            value = 0.6
        if root in ('bottle', 'turtle', 'gentle'):
            value = 1.3
        if root in ('handle', 'needle', 'cycle'):
            value = 1.9
        if root.endswith('angle'):
            value = max(0.4, 2.8 - 0.47 * max(0, len(root) - 5))
        if root in ('cattle', 'seattle'):
            value = 0.1
        if root.endswith('ffle'):
            value = 2.4
        if root == 'unable':
            value = 0.85
        if root in WEAK or root == 'ample':
            value = 0.05
        if text[:1].isupper() and value > 1.5:
            value += 0.4
        if root == 'little' and text[:1].isupper():
            value = 2.1
        if root == 'itle':
            value = 1.65
        if root == 'emple' and not attached:
            value = 0.8
        if ending.group(2) == 'es':
            value *= 0.8
        elif ending.group(2) in ('ed', 'ing'):
            value *= 0.6
        if attached and len(text) <= 5 and value > 1:
            value *= 1.2
        elif not attached and root in ('ble', 'gle', 'fle', 'kle'):
            value *= 0.65
    elif low in ('le', 'les', 'led', 'ling'):
        last = previous_letter.lower() if attached else ''
        if last in STOPS:
            value = 1.9
        elif last in 'fhjmnrswzy' and last:
            value = 0.9
        else:
            value = 0.4
        if last in 'uy':
            value = 1.2
        if not attached or not previous_letter:
            value = 0.03
        if low in ('led', 'ling'):
            value *= 0.6
    elif low in ('ile', 'iles', 'ville') and attached:
        value = 0.8
    elif low in ('el', 'ember') and attached:
        value = 0.35
    elif low in ('family', 'families'):
        value = 0.8
    elif low in ('belly', 'valley'):
        value = 1.8 if low == 'belly' else 0.6
    elif low == 'of':
        value = 0.27 * previous_value
    elif token.endswith(('个', '個')):  # General Chinese classifiers.
        value = 0.7
    elif token == '苹果':  # Apple, a strong -ple example, in Chinese.
        value = 2.0
    elif token in ('ブル', '들'):
        value = 1.5
    elif token == 'ル':
        value = 0.4
    return (doc, last_letter, value), float(value)

