programs.sol:
"""Checking/retrieval words, especially in procedural descriptions.

The response is negative for checking and getting information. It strengthens in
code comments and declarations, weakens for ordinary prose uses of 'get', and
continues onto an immediately following article, condition, or verb suffix.
Listed Chinese equivalents share these rules. Carry resets between documents.
Other words are left at zero; many small activations remain unmodeled.
"""
import re

READS = ()
RETRIEVAL = {'get', 'retrieve', 'fetch'}
SETTING = {'set', 'reset', 'clear', 'initialize', 'assign', 'init'}
UPDATING = {'update', 'change', 'increment', 'decrement'}
VERIFICATION = {'verify', 'validate', 'inspect'}
IO = {'load', 'read', 'save'}
ACTIONS = set(
    'add create remove delete write find generate convert calculate copy '
    'move insert attach enable disable start stop open close show use '
    'make prepare begin determine compute look download print extract'.split()
)
VERBS = (RETRIEVAL | SETTING | UPDATING | VERIFICATION | IO | ACTIONS
         | {'check', 'return'})
GRAMMAR = set(
    "i you we they he she it not will would should can could may must "
    "to and or".split()
)
GRAMMAR |= {"'t", '’t'}
DECLARATIONS = set('def function func void int String bool float double char '
                   'const var let'.split())
CHINESE = {'获取': 'get', '获得': 'get', '查询': 'retrieve', '查看': 'retrieve',
           '检查': 'check', '设置': 'set', '清除': 'clear', '返回': 'return',
           '如果': 'if', '当': 'when'}


def form_of(token):
    # Ignore punctuation prefixes; recognize inflections and CamelCase names.
    word = token.lstrip(' \t\r\n._-/(@#')
    if word in CHINESE:
        return CHINESE[word], '', False, False
    m = re.match(r'[A-Z]?[a-z]+|[A-Z]+', word)
    if not m:
        return '', '', False, False
    head = m.group()
    root, ending = head.lower(), ''
    for suffix in ('ing', 'ed', 'er', 's'):
        stem = root[:-len(suffix)] if root.endswith(suffix) else ''
        if stem in {'gett', 'sett'}:
            stem = stem[:-1]
        if stem not in VERBS and stem + 'e' in VERBS:
            stem += 'e'
        if stem in VERBS:
            root, ending = stem, suffix
            break
    tail = word[len(head):]
    return root, ending, head[0].isupper(), bool(tail and tail[0].isalpha())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev, echo = ('', 0.0) if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    root, ending, capital, compound = form_of(token)
    spaced = token.startswith(' ')
    comment = bool(re.search(r'(//+|/\*+|#|\*)\s*$', prev))
    declaration = prev.strip() in DECLARATIONS
    code = prev.strip() in {'{', '}', '>', '=', ')', ';', ':', '=>'} or (
        prev.isspace() and len(prev) > 1)
    # Strength is the magnitude of this component's negative response.
    strength = 0.0
    if root in VERBS:
        if root == 'check':
            strength = 0.74
            if ending == 's':
                strength += 0.15
            elif ending == 'ed':
                strength -= 0.20
        elif root in RETRIEVAL:
            strength = 0.60 if spaced or token.startswith('.') else 0.78
            if token.startswith('_'):
                strength += 0.25
            if root == 'get' and spaced and prev.strip().lower() in GRAMMAR:
                strength -= 0.35
            if compound or ending == 'ing':
                strength -= 0.35
        elif root == 'set':
            strength = 0.10 if spaced else 0.20
        elif root == 'update':
            strength = 0.25
        elif root in UPDATING | VERIFICATION | IO:
            strength = 0.10
        elif root == 'return' and ending == 's':
            strength = 0.24
        if capital:
            if spaced and root in {'check', 'get', 'set', 'return'}:
                strength += 0.18
            else:
                strength += 0.08
        if comment:
            if root == 'get':
                strength += 0.70
            else:
                strength += 0.58 if root in {'check', 'set'} else 0.45
        if declaration:
            strength += 0.50 if root in {'get', 'set'} else 0.25
        elif code and root != 'check':
            strength += 0.22 if root in {'get', 'set'} else 0.07
        if ending == 's' and root != 'check' and (comment or capital):
            strength += 0.30
        if (ending in {'ed', 'ing'} and root not in {'check', 'get'}
                and not comment):
            strength *= 0.3
        if root == 'set' and ending == 'er':
            strength = 0.22
    value = -max(0.0, strength)
    if root in {'if', 'when'}:
        if comment:
            value = -0.35 if prev.rstrip().endswith('*') else -0.65
        if not comment and echo < -0.10:
            value = (0.48 if root == 'if' else 0.30) * echo
        elif not comment and root == 'if' and prev.strip().lower() == 'only':
            value = -0.25
        elif (not comment and root == 'when' and prev.strip().lower()
              in {'call', 'called', 'invoked', 'triggered'}):
            value = -0.85
    if token == ' the':
        value = 0.45 * min(0.0, echo)
    elif token in {' that', ' whether'}:
        value = (0.15 if token == ' that' else 0.40) * min(0.0, echo)
    elif token in {'s', 'es', 'ing', 'ed', 'er'}:
        factor = 1.0 if token == 's' else 1.5 if token == 'es' else 0.35
        value = factor * min(0.0, echo)
    return (doc, token, value), float(value)

programs.haiku:
"""Layer-0 MLP component 4588 (down_proj).

Fires negatively on the word "get" or "check" (and "retrieve", "Returns") wherever it
starts a word, identifier or line: "Get", "Check", ".get(", "# check", "/* Retrieve".
Such a verb is strongly negative (about -0.9 to -1.0); in plain prose ("to get", "let me
check") it is weaker. Weaker still for "set", "load", "update", "restore", "verify" and
"read". The word right after a strong verb ("Check the", "Returns the", "Checks if") is slightly
negative. Everything else, including bare "return" and "create", is about zero.
"""

READS = ()

STRONG = {"check": -0.95, "get": -0.9, "retrieve": -0.9, "returns": -0.7}
WEAK = {"set": -0.25, "load": -0.25, "update": -0.25, "restore": -0.25, "verify": -0.25, "read": -0.1}
# Inflected forms that carry the same verb.
FORMS = {
    "checks": "check", "checking": "check", "checked": "check",
    "gets": "get", "getting": "get", "retrieves": "retrieve",
    "sets": "set", "loads": "load", "updates": "update",
}
PROSE_FACTOR = 0.45  # a lowercase verb with a space before it, after a word


def word_of(token):
    """The lowercased word in a token, without leading space or code punctuation."""
    w = token.strip().lstrip("._#@(\"'$-").lower()
    return FORMS.get(w, w)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = word_of(token)
    if len(prefix) > 1:
        before = prefix.token_strings[-2]
        if token in (" the", " a", " if") and before.strip() and word_of(before) in STRONG:
            return carry, -0.3
    if word in STRONG or word in WEAK:
        value = STRONG.get(word, WEAK.get(word))
        if word != "check" and token.startswith(" ") and token[1:2].islower() and len(prefix) > 1:
            if prefix.token_strings[-2].strip()[-1:].isalpha():
                value *= PROSE_FACTOR
        return carry, value
    return carry, 0.0

programs.luna:
"""Approximate a sparse negative response to software-operation words.
Check/get and setter names are stronger cues; a few common API verbs are weaker ones.
"""

READS = ()

CORE_OPERATIONS = frozenset({
    "insert", "load", "returns", "update", "updated", "updating",
    "verify", "verifying",
})
OTHER_OPERATIONS = frozenset({
    "add", "create", "creating", "find", "save",
})


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1].strip()
    letters = "".join(char for char in raw if char.isalpha())
    word = letters.lower()
    camel_get = word.startswith("get") and len(letters) > 3 and letters[3].isupper()
    camel_set = word.startswith("set") and len(letters) > 3 and letters[3].isupper()

    if word.startswith("check"):
        value = -0.78
    elif word.startswith("get") and (
        len(letters) == 3 or camel_get or word in {"gets", "getting"}
    ):
        value = -0.65
    elif word == "set" or camel_set:
        value = -0.4
    elif word in CORE_OPERATIONS:
        value = -0.28
    elif word in OTHER_OPERATIONS:
        value = -0.18
    else:
        value = 0.0
    return None, value

programs.sol:
"""Approximate a detector of exposed x/X and immediate continuations.

Tokens whose letters are all x, x-initial fragments, and differential dx
respond strongly; an internal x in an ordinary word is usually ignored.
XML/XOR are weaker lexical units. An x symbol at the very start of a
document is boosted. An x-ending fragment also leaves a short-lived trace on joined
letters, Roman numerals, or decimal digits. A blank can carry that trace
one more token, as in dimensions written "20 x 30".

These are spelling/formatting rules, not a token-id lookup. They omit the
component's smaller, idiosyncratic responses to unrelated words.
"""
READS = ()
ROMAN_LETTERS = frozenset('IVXLCDM')


def symbol_value(token):
    """Current-token signal, before any preceding-token trace."""
    word = token.strip().lower()
    letters = ''.join(c for c in word if c.isalpha())
    if letters and set(letters) == {'x'}:
        if len(letters) == 2:
            return 2.35 if token.startswith(' ') else 2.70
        if len(letters) >= 3:
            return 1.80 if token.startswith(' ') else 2.85
        if word.startswith('\\'):
            return 0.16
        if word.startswith(('(', '[', '{', ',', '=', '+', ')')):
            return 0.74
        if word.startswith('*'):
            return 0.64
        if word.startswith('-'):
            return 1.12
        if word.startswith('_'):
            return 0.88
        return 0.89 if token.startswith(' ') else 0.97
    if word.startswith(('xml', 'xor')):
        return 0.25
    if word.startswith('x') and word.isascii():
        if len(word) == 2 and word[1] in 'aeiou':
            return 0.55
        return 1.03 if len(word) <= 3 else 0.60
    if word == 'dx':
        return 0.66
    if len(word) == 2 and word.endswith('x'):
        if word[0] == 'o':
            return 0.49
        if word[0] not in 'aeiu':
            return 0.42
        if token.strip() == 'IX':
            return 0.30
    if word in {'-axis', '-ray'}:
        return 0.18
    return -0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        carry = (doc, 0.0, False)
    # Memory: document, strength of the last x-ending, and x + blank.
    _, old_strength, after_blank = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    letters = ''.join(c for c in word if c.isalpha())
    value = symbol_value(token)
    if first and letters == 'x':
        value *= 2.1
        if token == 'x':
            value += 1.15
        elif token == 'X':
            value += 0.80
    if old_strength:
        if token.isalpha():
            echo = 0.72 if len(token) <= 2 else 0.38
            if set(token.upper()) <= ROMAN_LETTERS:
                echo += 0.65
            value += old_strength * echo
        elif len(token) == 1 and token in '0123456789':
            value += old_strength * (0.77 - 0.045 * int(token))
        elif token == ' ':
            value += old_strength * 0.43
        elif word in {'-axis', '-ray'}:
            value += old_strength * 0.75
        elif value > 0.25 and 'x' in word:
            value += old_strength * 0.62
    if after_blank and len(token) == 1 and token in '0123456789':
        value += 0.30
    strength = 0.0
    if word.endswith('x'):
        if (len(letters) <= 2 and word != 'ex'
                and not word.startswith('\\')):
            strength = 1.0
        else:
            strength = 0.30
    return (doc, strength, token == ' ' and old_strength > 0.5), float(value)

"""Approximate the negative response to item-label and formatting delimiters.

Periods after line-opening numbers respond strongly, especially item 1.
Indentation weakens this; recent Han text without kana, or Cyrillic text,
strengthens it. Numeric/version points, letter labels and Markdown headings
have smaller responses. Periods bundled with following text are treated
separately. There are also rules for enumeration commas, bold markers and
closing diff-header markers. Most other tokens are zero.

The fitted strengths summarize training measurements. Retain only 160 recent
characters and clear them at document boundaries; lexical fluctuations are
not modeled.
"""
import re

READS = ()
MARKUP = {'##': -0.40, '###': -0.46, '####': -0.35, '#####': -0.13}
LABEL_WORDS = r'section|sec\.?|chapter|question|q|exercise|ex\.?|lesson|item|step|part'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    line = text.rsplit('\n', 1)[-1]
    number = re.search(r'[0-9０-９]+$', line)
    label = re.fullmatch(r'([\s#*•>\-]*)([0-9０-９]+)', line)
    value = 0.0

    if token.startswith(('.', '．')) and number:
        digits = number[0]
        length = len(digits)
        before = line[:number.start()]
        if token in {'.', '．'}:
            value = -0.19 if length <= 2 else -0.13
            if before.endswith('.'):
                value = -0.51 if length <= 2 else -0.20
            if label:
                value = -1.15 if length <= 2 else -0.76 if length == 3 else -0.45
                if label[1]:
                    value += 0.46 if label[1].isspace() else 0.20
                if digits in {'1', '１'}:
                    value -= 0.20
                recent = text[-100:]
                han = sum('\u3400' <= c <= '\u9fff' for c in recent) > 3
                kana = any('\u3040' <= c <= '\u30ff' for c in recent)
                if han and not kana:
                    value -= 0.40
                elif sum('\u0400' <= c <= '\u052f' for c in recent) > 3:
                    value -= 0.14
            elif re.fullmatch(r'[\s#*•>\-]*\d+(?:\.\d+)+', line):
                value = -0.70
            elif re.fullmatch(r'[\s#*•>\-]*(?:' + LABEL_WORDS + r')\s*\d+',
                              line, re.I):
                value = -0.84
            elif re.search(r'\\n\s*#+\s*\d+$', line):
                value = -0.98
            elif re.search(r'\\n\s*\d+$', line):
                value = -0.40
        elif token[1:].isspace():
            value = -0.40 if label else 0.015
        elif token[1:2].isupper():
            value = -0.90 if label else -0.55
            if not label and before[-1:].isalpha() and length <= 2:
                value = -0.75
        elif token[1:2].islower():
            value = -0.08
        else:
            value = -0.16
    elif token == '.' and re.fullmatch(r'[\s#*•>\-]*(?:[A-Za-z]|[IVXLCDM]+)', line):
        value = -0.55 if line.strip().islower() else -0.35
    elif token == '、':
        if number:
            value = -1.70 if label else -0.85
        elif re.fullmatch(r'\s*[一二三四五六七八九十百]+', line):
            value = -0.80
        else:
            value = 0.035
    elif token.startswith(')'):
        value = 0.04 if number else -0.015
        if token == ')' and re.fullmatch(r'\s*\(?(?:\d{1,3}|[A-Za-z])', line):
            value = -0.50
    elif token.strip() in MARKUP:
        value = MARKUP[token.strip()]
    elif token == ' @@':  # closing marker of a diff hunk header
        value = -0.80
    elif token == ' **':  # space followed by an emphasis-opening marker
        value = -0.22
    return (doc, (text + token)[-160:]), value

programs.haiku:
"""List-label periods: a period or other closing mark that follows a list number or letter label at the start of a line."""

READS = ()

ROMAN = {"i", "ii", "iii", "iv", "v", "vi", "vii", "viii", "ix", "x",
         "I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX", "X"}


def starts_line(s, k):
    j = k - 1
    while j >= 0 and s[j].strip() == "" and "\n" not in s[j]:
        j -= 1
    return j < 0 or "\n" in s[j]


def step(carry, prefix, upstream):
    s = prefix.token_strings
    t = prefix.position
    cur = s[t]
    if t == 0:
        return None, 0.0
    if cur in {"###", "##"}:
        return None, -0.5 if starts_line(s, t) else 0.0
    if cur not in {".", ")", "、", "．"}:
        return None, 0.0
    label = s[t - 1]
    line_start = starts_line(s, t - 1)
    if label.isdigit() and len(label) <= 2:
        if line_start:
            return None, -1.2 if cur == "." else -0.5
        return None, -0.2 if cur == "." else 0.0
    if label.isalpha() and (len(label) == 1 or label in ROMAN):
        if line_start and cur == ".":
            return None, -0.3
        return None, 0.0
    return None, 0.0

programs.luna:
"""Predict negative cues for simple text-format markers.

This recognizes a period after a line-start number (also in a block quote), a
closing parenthesis after a short parenthesized label, or Markdown hash marks
at the start of a blank line. It predicts zero elsewhere.
"""

READS = ()
HEADING_MARKS = {"#", "##", "###", "####", "#####", "######"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history = ""
    else:
        history = carry[1]

    label = history.rsplit("\n", 1)[-1].strip()
    while label.startswith(">"):
        label = label[1:].lstrip()

    numbered_period = (
        token in {".", "．", "。", "、"}
        and label
        and all(char.isdecimal() for char in label)
    )
    parenthesized_label = (
        token == ")"
        and len(label) in (2, 3)
        and label[0] == "("
        and all(char.isalnum() for char in label[1:])
    )
    markdown_heading = not label and token.strip() in HEADING_MARKS

    if numbered_period:
        value = -1.2
    elif parenthesized_label:
        value = -0.65
    elif markdown_heading:
        value = -0.2
    else:
        value = 0.0
    history = (history + token)[-100:]
    return (doc, history), value

