"""Approximate a lexical response to sets, spaces, and related object words.

The strongest negative predictions occur on 'the set', mathematically
qualified sets, vector/Hilbert spaces, and split subspace compounds. Literal
set/space stems can also respond inside identifiers. A following 'of' gets a
phrase-specific response, disambiguating otherwise ambiguous collection nouns.
Related object words have smaller responses; unmatched text is zero. Capital
letters and code member-name prefixes attenuate most predictions. The bounded
text tail and previous-word state reset at each document boundary.
"""
import re

READS = ()
SET_MODIFIERS = set('''finite infinite empty nonempty bounded closed open
    convex measurable invariant generating solution training test parameter
    data vertex edge universal feasible countable dimensional full entire'''.split())
VECTOR_MODIFIERS = set('''vector hilbert banach affine euclidean dimensional
    dimension dual moduli normed separable complex linear'''.split())
ABSTRACT_SPACES = set('''metric parameter phase null solution state embedding
    probability sample functional configuration tangent design model'''.split())
STRONG_COLLECTIONS = {'subset', 'subsets', 'multiset', 'subgroup', 'subgroups'}
MATH_OBJECTS = set('''graph graphs interval intervals domain domains lattice
    lattices manifold manifolds plane planes algebra union partitions'''.split())
DERIVED_SPACES = {kind + 'space' for kind in VECTOR_MODIFIERS | ABSTRACT_SPACES}
COMPOUNDS = STRONG_COLLECTIONS | DERIVED_SPACES | {
    'dataset', 'datasets', 'subspace', 'subspaces', 'hyperspace', 'hyperspaces',
    'emptyset', 'codomain'}
SOFT_OBJECTS = set('''family families sequence sequences class classes
    system systems basis range intersection'''.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        text, last, old = '', '', 0.0
    else:
        text, last, old = carry[1:]
    token = prefix.token_strings[-1]
    joined = text + token
    words = re.findall(r'[A-Za-z]+', joined)
    end = re.search(r'[A-Za-z]+\Z', joined)
