    prior = words[-2].lower() if len(words) > 1 else ''
    piece = re.search(r'[A-Za-z]+\Z', token)
    stem = piece.group().lower() if piece else ''
    math = bool(re.search(r'[$\\∈⊂∀∃∑∫]|\b(vector|matrix|algebra|'
                          r'equation|theorem|finite|convex|dimensional)\w*', text.lower()))
    if stem in {'set', 'sets', 'space', 'spaces', 'problem', 'problems'}:
        if word not in COMPOUNDS:
            if word != stem:
                prior, math = '', False
            word = stem
    value = 0.0
    if word in {'set', 'sets'}:
        value = -0.95 if word == 'sets' else -0.65
        if prior == 'the':
            value = -2.0
        elif prior in {'a', 'an'}:
            value = -1.35
        elif prior in {'this', 'that', 'these', 'those'}:
            value = -1.0
        elif prior in SET_MODIFIERS:
            value = -2.1
        elif prior in {'to', 'is', 'was', 'were', 'be', 'been', 'should',
                       'not', 'never', 'already', 'can', 'on', 'as'}:
            value = -0.25
        elif prior == 'me':
            value = -1.4  # 'Let me set' introduces an assignment.
    elif word in {'space', 'spaces'}:
        value = -0.9 if math else -0.3
        if prior in VECTOR_MODIFIERS:
            value = -2.8
        elif re.search(r'\d\s*[dD]\s*\Z', text):
            value = -1.5
        elif prior in ABSTRACT_SPACES:
            value = -2.1
        elif prior == 'the':
            value = -1.05
    elif word in {'subspace', 'subspaces', 'hyperspace', 'hyperspaces'}:
        value = -3.3 if word.startswith('sub') else -2.5
    elif word in DERIVED_SPACES:
        value = -2.3
    elif word in {'hyperplane', 'hyperplanes', 'subinterval', 'subintervals'}:
        value = -1.5
    elif word in STRONG_COLLECTIONS:
        value = -1.35
    elif word in {'dataset', 'datasets', 'emptyset', 'codomain'}:
        value = -0.9
    elif word in {'problem', 'problems'}:
        value = -0.5 if word == 'problem' else -0.38
        if prior == 'the' and word == 'problem':
            value = -0.82
        elif prior in {'optimization', 'linear', 'decision', 'original'}:
            value = -1.1
    elif word in {'case', 'cases'}:
        value = -0.18 if word == 'case' else -0.07
        if prior == 'the':
            value = -0.5
        elif prior in {'special', 'general', 'base'}:
            value = -1.0
        elif prior == 'test':
            value = -0.4
        elif not text.rsplit('\n', 1)[-1].strip():
            value = 0.0  # A line-initial case token, often a switch label.
    elif word in {'region', 'regions'}:
        value = -0.9 if prior == 'the' else -0.55
    elif word in MATH_OBJECTS:
        value = -0.65
    elif word in SOFT_OBJECTS:
        value = -0.18
    elif word in {'sub', 'subs', 'dimensional', 'convex'}:
        value = -1.1 if word == 'subs' else -0.3
    elif word == 'of':
        if last == 'set':
            value = -0.8 + 0.4 * min(old, 0.0)
        elif last in STRONG_COLLECTIONS or last in {'space', 'spaces'}:
            value = -1.1
        elif last in {'class', 'classes', 'family', 'families'}:
            value = -0.7
        elif last in {'collection', 'collections', 'problem', 'problems'}:
            value = -0.33
        elif last == 'sets':
            value = -0.9
        elif last in {'subspace', 'subspaces'}:
            value = -1.5
        else:
            value = 0.7 * min(old, 0.0)
    if word not in {'subspace', 'subspaces', 'hyperspace', 'hyperspaces'}:
        if token.startswith(('.', '_', '/')) or token.strip().isupper():
            value *= 0.5
        elif token.strip()[:1].isupper():
            value *= 0.75
    echo = value if word != 'of' else 0.0
    return (doc, joined[-100:], word, echo), float(value)

"""Approximate a context-sensitive English definite-article signal.

The token ' the' gets a positive response, strongest after 'both', then
'either'/'neither' or prepositions such as 'between'. After commas,
conjunctions and forms of 'be', it is weaker or slightly negative.
Capitalization and attached whitespace matter. Other determiners have a
small negative baseline, with positive responses after pair quantifiers;
prepositions after 'both' also receive a positive response. Other tokens
are ignored. Only the previous token is remembered, resetting by document.
"""
READS = ()

# Prepositions grouped by their observed strength before the article.
PREPOSITION_GROUPS = (
    (2.55, 'between'),
    (1.9, 'among'),
    (1.7, 'from across toward towards inside near'),
    (1.55, 'of on at during within under around throughout outside'),
    (1.4, 'for over after without along beyond behind beside'),
    (1.25, 'to with by through into against upon below via'),
    (1.1, 'in before onto above off'),
    (0.95, 'about until'),
)
PREPOSITIONS = {
    word: value
    for value, words in PREPOSITION_GROUPS
    for word in words.split()
}
COPULAS = frozenset('am is are was were be been being'.split())
POSSESSIVES = frozenset('my your his her its our their'.split())
DETERMINERS = POSSESSIVES | frozenset(
    'this that these those each every either neither another'.split()
)


def article_strength(previous):
    word = previous.strip().lower()
    if word == 'both':
        return 5.2
    if word in ('either', 'neither'):
        return 2.35
    if word in PREPOSITIONS:
        return PREPOSITIONS[word]
    if word in ('all', 'only'):
        return 1.38
    if word in COPULAS or word in ("'s", '’s'):
        return -0.2
    if (',' in previous or ';' in previous
            or word in ('so', 'then', 'perhaps', 'maybe')):
        return 0.07
    if word in ('and', 'but', 'that', 'because', 'while'):
        return 0.3
    if word in ('or', 'if', 'which', 'as', 'when', 'since'):
        return 0.55
    if word in ('than', 'using', 'use'):
        return 0.85
    return 0.5


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    prev_word = previous.strip().lower()

    if token == ' the':
        value = article_strength(previous) if previous else 1.12
    elif token == '-the':
        value = 1.05
    elif token == 'the' or token == '\tthe':
        value = PREPOSITIONS.get(prev_word, 0.44)
    elif lower == 'the' and word.isupper():
        value = 1.0 if token.startswith(' ') else 0.35
    elif word == 'The':
        value = -0.07
    elif lower in DETERMINERS or lower in ('a', 'an'):
        value = -0.07 if lower in DETERMINERS else -0.02
        if prev_word == 'both':
            value = 2.5
        elif prev_word in ('either', 'neither'):
            value = 1.25
        elif prev_word == 'between':
            value = 0.65
    elif prev_word == 'both' and lower in PREPOSITIONS:
        value = 1.1
    else:
        value = 0.0
    return (doc, token), value

programs.luna:
"""Predict a localized response to the lowercase article, with grammatical cues.

Most of the response is on " the". It tends to be stronger after prepositions,
especially in "between the" and "both the", and is muted after copulas such as
"is". Other tokens are predicted to have no contribution.
"""
READS = ()

PREPOSITIONS = {
    " of", " in", " to", " on", " with", " at", " for", " from", " by",
    " under", " within", " over", " through", " into", " about", " after",
    " during", " across", " inside", " around", " against", " along",
    " below", " off", " throughout", " towards",
}
COPULAS = {" is", " are", " was", " be"}

def step(carry, prefix, upstream):
    article = prefix.token_strings[-1]
    if article == "the":
        return None, 0.4
    if article != " the":
        return None, 0.0

    if len(prefix.token_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        before = ""
    else:
        before = prefix.token_strings[-2]

    if before == " both":
        return None, 4.7
    if before == " between":
        return None, 2.5
    if before in PREPOSITIONS:
        return None, 1.4
    if before in COPULAS:
        return None, -0.2
    if before == " as":
        return None, 0.55
    if before in {" and", " that", ","}:
        return None, 0.3
    return None, 0.9

programs.sol:
"""A local lexical detector for India and its cultural neighbourhood.

Places, names, languages, religion and money supply positive lexical cues.
Smaller cues include Indic name endings, formal enumeration words,
aspirated-consonant spellings, and Chinese Buddhist words and transliterations. These rules respond to spelling, even when
it occurs outside an Indian context; they do not classify an entire document.

State retains only the preceding token and an Indic-script hint, resetting at
new documents. Decoded text is consulted only for split Unicode characters.
Diffuse non-Indic responses and fine contextual variation are left unmodelled.
"""
READS = ()

# Approximate strengths of familiar lexical groups, learned on training text.
CUES = tuple((value, frozenset(words.split())) for value, words in (
    # Indian places and political vocabulary.
    (6.0, '''Delhi Mumbai Kolkata Kerala Karnataka Maharashtra Gujarat
        Chennai Hyderabad Bihar Pradesh Nadu Sabha Haryana'''),
    (4.6, 'Bombay Bengal Kashmir Punjab Pune Rajasthan Uttar Nagar'),
    (4.5, 'India Indian'),
    # Personal names, and stems of names and religious vocabulary.
    (5.7, 'Singh Gandhi Modi Brah Bollywood'),
    (5.3, 'Hindi Hindu Hindus Sikh Urdu Krish Krishna'),
    (4.6, 'Kumar Sharma Kapoor Patel Gupta Rahul Narendra Jain Bhar Vish Chand'),
    (2.4, 'Raj Shank Sri Rahman Ahmed Aad Vij Yog Shiv Ved Mahar Lal Rao Mandal Khan Goa'),
    (1.3, '''Dev Ram Shah Sah Bose Dh Muk Moh Kh Khal Lak Kath Kann Nath
        Saras Vive Chatt Gur Hind Beng Lok Gov Vid Sr Pur Ali Malay'''),
    # Neighbouring countries, religions and cultural terms.
    (3.3, 'Nepal Bangladesh Pakistani Karachi Lahore Islamabad'),
    (2.7, 'Pakistan'),
    (1.4, '''Islam Muslim Muslims Islamic mosque Mosque mosques Quran Qur
        Ibrahim Muhammad Mohammed Mohamed Mohammad Imam Allah Abdullah
        Abdul Ahmad Abu Taliban'''),
    (1.6, 'Buddha Buddh Buddhist Buddhism'),
    (3.5, 'yoga Yoga Bangalore crore ₹ Himal'),
    (2.1, 'guru Guru mantra caste Lanka Rs Indians'),
    (3.1, 'Tamil Bh bh Tantra'),
    (4.6, 'lakh Pvt BJP'),
    (0.9, 'temple meditation vegetarian elephant tribal mango Fiji Trinidad'),
    (1.5, 'cricket Cricket Bali bali Burma burma Myanmar myanmar Persian persian İslam'),
    (0.5, 'tea'),
))

# Common place/name endings: e.g. -pur, -abad, Rajendra, Prakash, Sharma.
ENDINGS = {
    'abad': 3.0, 'pur': 2.1, 'apur': 3.0, 'ipur': 3.4, 'nagar': 3.5,
    'endra': 2.6, 'akash': 3.7, 'abh': 3.1, 'hatt': 3.0, 'hya': 4.0,
    'atha': 1.4, 'athi': 1.8, 'jee': 1.4, 'arya': 1.3, 'ashi': 0.9,
    'esh': 0.9, 'umar': 2.1, 'harma': 2.8, 'akra': 2.1, 'indh': 2.1,
    'krit': 3.7, 'ya': 0.6, 'ali': 0.6, 'ala': 0.4, 'aram': 0.8,
    'akh': 1.1, 'han': 0.6, 'ham': 0.4, 'aya': 0.4,
    'ugu': 0.7, 'alam': 0.8, 'wal': 0.6, 'aga': 0.5,
    # Haryana, Maharashtra, Mumbai, Bangalore, Jammu, Bihar, Bangladesh.
    'aryana': 6.5, 'ashtra': 5.1, 'umbai': 5.1, 'alore': 4.4,
    'ammu': 2.4, 'ihar': 2.2, 'ladesh': 3.3,
}
CHINESE_CUES = {'印度': 3.5, '瑜伽': 3.5, '佛教': 2.4, '婆': 3.0}
CHINESE_CUES.update(dict.fromkeys('佛菩陀迦娑梵', 1.4))
CHINESE_CUES.update(dict.fromkeys('蓮莲', 0.9))
ASPIRATED_LETTERS = frozenset('भघधखफथਝਛਭਘਧਖਫਥ')
H_COMPLETIONS = {
    'h': 1.3, 'ha': 1.9, 'hi': 1.4, 'hu': 1.9, 'har': 2.1,
    'han': 1.3, 'ham': 0.8, 'hai': 3.0, 'hy': 2.3, 'hs': 1.9, 'he': 0.4,
}
SCRIPT_BASE = {'devanagari': 0.45, 'gurmukhi': 0.25, 'other_indic': 0.25}
SCRIPT_LEAD = {'devanagari': 2.2, 'gurmukhi': 1.8, 'other_indic': 0.8}


def script_of(text):
    for c in reversed(text):
        if '\u0a00' <= c <= '\u0a7f':
            return 'gurmukhi'
        if '\u0900' <= c <= '\u097f':
            return 'devanagari'
        if '\u0980' <= c <= '\u0dff':
            return 'other_indic'
    return None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', None, prefix.position)
    _, old, script, start = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    value = next((v for v, words in CUES if word in words), 0.0)
    if not token[:1].isspace():
        value *= 0.8
    value = ENDINGS.get(token, CHINESE_CUES.get(token, value))
    if token == '.in':
        value = 1.3
    if word.islower() and word in {'india', 'indian', 'hindi'}:
        value = 2.9

    # Consonant digraphs split across tokens, especially bh/dh/gh/kh.
    if old[-1:].lower() in {'b', 'd', 'g', 'k'} and (
        token.startswith('h') and token.isascii() and token.isalpha()
    ):
        sound = H_COMPLETIONS.get(token, 1.0 if len(token) <= 3 else 0.0)
        value = max(value, sound)
    elif token == 'h' and old[-1:].lower() in {'s', 'z', 't', 'p', 'r'}:
        value = max(value, 0.4)

    # Recognisable continuations of Vedic/Ayurveda and a few Indian names.
    if token == 'edic':
        value = 4.7 if old.strip() == 'V' else 1.8
    if token == 'urved':
        value = 4.8 if old.strip().lower() == 'ay' else 2.0
    for ending, stem, strength in (
        ('a', 'urved', 5.3), ('ar', 'shank', 2.1), ('ra', 'mish', 1.7),
        ('u', 'nehr', 2.5), ('ali', 'beng', 3.2),
    ):
        if token == ending and old.lower().endswith(stem):
            value = strength
    if word in {'Similarly', 'respectively', 'etc'}:
        value = 0.45
    if word == 'above':
        value = 0.5 if old == ' the' else 0.25
    if token in {'ā', 'ī'}:
        value = 0.8

    current_script = script_of(token)
    if current_script:
        value = max(value, SCRIPT_BASE[current_script])
    if token in ASPIRATED_LETTERS:
        value = max(value, 1.5)
    if '\ufffd' in token:
        # Reconstruct only to identify a split character, within this document.
        text = prefix.text_prefixes[-1]
        if start:
            text = text[len(prefix.text_prefixes[start - 1]):]
        text = text[-12:]
        current_script = script_of(text)
        if current_script:
            script = current_script
        elif any(c.isalpha() for c in text):
            script = None
        if script and token.strip() == '\ufffd':
            if text.endswith('\ufffd'):
                value = 0.9 if token[:1].isspace() else SCRIPT_LEAD[script]
            else:
                value = 0.1 if script == 'gurmukhi' else 0.2
                if text[-1:] in ASPIRATED_LETTERS:
                    value = 1.5
    elif current_script:
        script = current_script
    elif any(c.isalpha() for c in token):
        script = None
    return (doc, token, script, start), float(value)

