"""Flag a few South Asian cultural and religious words, where this component
is unusually active; leave ordinary text at zero."""
READS = ()

SOUTH_ASIAN = {
    "india", "indian", "hindi", "hindu", "yoga", "guru", "punjabi",
    "punjab", "nepal", "pakistan", "pakistani", "bangladesh", "bengali",
    "khan", "nabil", "shaban", "punya",
}
ISLAMIC = {"muslim", "imam", "islam", "islamic", "allah", "khomeini"}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent = ""
    else:
        recent = carry[1]
    recent = (recent + prefix.token_strings[-1])[-80:]
    word = ""
    for ch in reversed(recent):
        if ch.isalpha():
            word = ch + word
        else:
            break
    key = word.casefold()
    if key in SOUTH_ASIAN:
        value = 2.0
    elif key in ISLAMIC:
        value = 1.0
    else:
        value = 0.0
    return (doc, recent), value

