"""Weak grammatical-word responses plus stronger noun-compound completions.

English measurement nouns are sensitive to their modifier: "expected value"
is positive, while "low-cost" is negative. Chinese compound endings behave
similarly: commemorative objects and fees are positive, while whole-set and
extent expressions can be negative. Small grammatical and formatting classes
provide a background approximation. Many other small lexical effects are
left at 0.002 rather than memorized in a vocabulary table.
"""

READS = ()

# These are linguistic classes, with empirical activation offsets.
BACKGROUND = (
    ("speaker pronouns", "I me we us", -0.009),
    ("animate pronouns", "he she him", -0.021),
    ("plural possessive", "their", 0.044),
    ("singular demonstratives", "this that", -0.008),
    ("plural demonstratives", "these those", 0.031),
    ("ability modals", "can could", -0.016),
    ("conditional modal", "would", -0.037),
    ("motion prepositions", "over under through across into onto toward towards", -0.028),
    ("alternatives", "either neither", -0.062),
    ("paired quantity", "both", 0.038),
    ("multiplicity", "single double triple quadruple", -0.054),
    ("age adjectives", "new old young ancient modern", -0.023),
    ("natural/artificial", "natural artificial synthetic", -0.069),
    ("static/dynamic", "static dynamic", -0.066),
    ("additional quantity", "additional existing remaining", -0.043),
    ("size adjectives", "small big large tiny huge enormous", -0.027),
    ("manner adverbs", "easily simply exactly clearly quickly slowly", 0.036),
    ("time adverbs", "previously currently subsequently finally eventually again", 0.031),
    ("addition", "also moreover furthermore too", 0.020),
    ("contrast", "although though despite however", 0.027),
)
BACKGROUND = tuple((name, frozenset(words.lower().split()), value)
                   for name, words, value in BACKGROUND)

MEASUREMENTS = frozenset("""
value values number numbers amount amounts rate rates level levels cost costs
fee fees price prices time times wave waves length speed size
""".split())
EXTENT = frozenset("""
high low higher lower large small big little full whole all any every single
one two three next last short long infinite considerable
""".split())
STATISTICAL = frozenset("""
expected predictive average mean median nominal required estimated total
maximum minimum rational decimal binary atomic approximate
""".split())
PROCESS = frozenset("""
reaction response transmission failure production acceptance detection
survival participation firing transport scattering execution waiting hitting
registration membership transaction service maintenance computational
administrative correlation polynomial linear
""".split())

CJK_ENDINGS = frozenset("费費价價品册冊量数數率期片图圖稿函方型心")
CJK_EXTENT = frozenset("全无無一二三同随隨如按过過超大上下左右")
CJK_FUNCTION = frozenset("的地得了而和与與在是有不为為从從以到对對")


def is_cjk(text):
    return bool(text) and all("\u3400" <= c <= "\u9fff" for c in text)


def response(token, previous):
    word = token.strip().lower().lstrip("-")
    before = previous.strip().lower()
    if word in MEASUREMENTS and token[:1] in (" ", "-"):
        value = 0.0
        if word in {"rate", "rates", "level", "levels", "times"}:
            value = 0.06
        elif word in {"time", "cost", "costs", "price", "prices", "size", "speed", "numbers"}:
            value = -0.04
        elif word == "number":
            value = 0.025
        elif word in {"wave", "waves", "fees"}:
            value = 0.16
        elif word == "fee":
            value = 0.075
        if before in EXTENT:
            value -= 0.10
            if word in {"cost", "costs", "rate", "rates"}:
                value -= 0.08
        if before in STATISTICAL:
            value += 0.13
        if before in PROCESS:
            value += 0.22 if word in {"rate", "rates", "time", "times", "cost", "length"} else 0.07
        if before == "expected" and word in {"value", "number", "time", "amount", "cost", "rate"}:
            value = 0.58 if word == "value" else 0.43
        if word in {"rate", "rates"} and before in {
            "required", "reaction", "failure", "transmission", "annual"
        }:
            value = 0.43
        if word in {"wave", "waves"} and before in {
            "continuous", "standing", "electromagnetic", "symbolic"
        }:
            value = 0.34
        if token.startswith("-") and word in {"cost", "costs"} and before == "low":
            value = -0.49
