    if token in CJK_ENDINGS:
        descriptive = is_cjk(previous) and len(previous) >= 2
        value = 0.03
        if token in "费費":
            value = 0.52 if descriptive else 0.21 if is_cjk(previous) else 0.06
            if previous in {"交通", "医疗", "醫療", "廣告", "广告"}:
                value = 0.80
        elif token in "量价價":
            value = 0.34 if descriptive else 0.04
        elif token in "数數品型":
            value = 0.17 if descriptive else 0.01
        elif token in "册冊片":
            value = 0.23 if descriptive else 0.10
        elif token in "稿函":
            value = 0.35 if descriptive else 0.14
        elif token == "心":
            value = -0.12
        elif token == "率":
            value = 0.02 if descriptive else -0.07 if is_cjk(previous) else -0.27
            if previous in {"回报", "生产", "死亡", "转化", "录取", "命中"}:
                value = 0.30
        elif token == "期":
            value = 0.06 if descriptive else -0.04
        elif token in "图圖":
            value = 0.06 if descriptive else -0.06
        elif token == "方":
            value = 0.10 if descriptive else 0.03
            if previous in {"发送", "接收"}:
                value = 0.42
        if previous in CJK_EXTENT and token not in "费費册冊片函方":
            value = -0.40
        if previous in {"纪念", "紀念"} and token in "品册冊":
            value = 0.94
        if previous in {"全", "無", "无"} and token in "数數":
            value = -0.60
        if previous in {"全", "随", "隨"} and token == "心":
            value = -0.63
        if previous in {"全", "一"} and token == "品":
            value = -0.60
        if previous in {"一", "以上"} and token == "率":
            value = -0.74
        return value
    if token in {"规", "規"} and previous == "依":
        return -0.75

    value = 0.002
    if token.startswith(" "):
        for _, words, offset in BACKGROUND:
            if word in words:
                value += offset
        if word == "there":
            value = -0.035 if before in {"is", "are", "was", "were", "be", "out", "in"} else 0.065
    if token == "__":
        value = -0.031
    elif token == "\\t":
        value = -0.034
    elif token and all(c == "·" for c in token):
        value = 0.084
    elif token == "</think>":
        value = 0.067
    elif token == "<think>":
        value = -0.034
    return value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = "" if carry is None or carry[0] != document else carry[1]
    token = prefix.token_strings[-1]
    return (document, token), float(response(token, previous))

"""Approximate a lexical response to type, form, style, and expression.

Most tokens get zero; related English words, code spellings, and translations
get positive pulses with roughly fitted sizes. 式 and 식 are especially strong;
氏 (the surname/title character) is another observed response. The previous
token resolves split word endings and a few familiar compounds, resetting at
document boundaries. Decoded text resolves completed byte-split characters.
This omits the component's many smaller, less systematic responses.
"""
READS = ()
PUNCTUATION = '.,;:!?()[]{}<>\\/\"\'`=_+-*'


def lexical_value(s):
    bare = s.strip().strip(PUNCTUATION)
    word = bare.lower()
    if word in ('type', 'types'):
        if word == 'types':
            return 1.1 if s.startswith('-') else 0.87
        if s.startswith('_'):
            return 0.95
        if s.startswith('-') or s == 'Type' or s == '.type':
            return 1.3
        return 1.12
    if bare.endswith('Type'):
        return 0.8
    if word in ('typ', 'otype', 'otypes', 'dtype', 'ctype', 'typing'):
        return 0.45
    if word in ('style', 'styles'):
        if s.startswith('-'):
            return 1.83
        return 0.9 if s != 'style' else 0.47
    if word in ('format', 'formats'):
