Dedicated chat/tool/thinking delimiters have large positive responses. The
first message opener in a document is weaker. Away from boundaries, Unicode
fragments and CJK text get higher backgrounds than ASCII syntax; longer
alphabetic tokens and capitalized words get a modest content-word response;
mixed-case identifiers get an additional bump.
A few explicit lexical families describe discourse units, function arguments,
exclusive adverbs, and containment. 'Not only' weakens the response to 'only'.
These rules summarize training averages; individual positive and negative
word preferences remain unexplained, rather than hidden in a lookup table.
"""

READS = ()

BOUNDARIES = {
    '<|im_start|>': 3.37,
    '<|im_end|>': 4.53,
    '<tool_call>': 5.02,
    '</tool_call>': 2.73,
    '<tool_response>': 3.96,
    '</tool_response>': 3.04,
    '<think>': 2.35,
    '</think>': 2.25,
    '<|endoftext|>': 0.07,
}


def background(token):
    text = token.strip()
    # Discourse units, and code's abbreviations for function arguments.
    word = text.strip('._([-').lower()
    if word in {'message', 'messages', 'statement', 'statements',
                'sentence', 'sentences'}:
        return 0.95
    if word in {'comment', 'comments', 'paragraph', 'paragraphs'}:
        return 1.2
    if word in {'argument', 'arguments', 'arg', 'args'}:
        return 1.39 if text == 'arguments' else 0.8
    if word in {'argv', 'argc'}:
        return 1.9
    if word in {'only', 'merely', 'solely'}:
        return 0.85
    if word in {'contain', 'contains', 'containing', 'contained'}:
        return 0.78
    if '\ufffd' in text:
        return 0.42
    if any('\u3400' <= c <= '\u9fff' for c in text):
        return 0.16 + 0.13 * max(0, min(len(text), 4) - 2)
    letters = ''.join(c for c in text if c.isalpha())
    if not letters:
        return 0.0
    if not letters.isascii():
        return 0.075
    value = 0.018 * max(0, min(len(letters), 9) - 3)
    if letters.istitle():
        value += 0.055
    elif not letters.islower() and not letters.isupper():
        value += 0.50
    return value


