        value = 2.79
    elif token == '<|im_end|>' and not first:
        previous = prefix.token_strings[-2]
        value = 4.31 if previous == '</tool_response>' else 4.60
    elif token.strip().lower() == 'only' and not first:
        # 'Not only' is additive, rather than a plain restriction.
        previous = prefix.token_strings[-2].strip().lower()
        value = 0.37 if previous == 'not' else 0.90
    else:
        value = BOUNDARIES.get(token)
        if value is None:
            value = background(token)
    return doc, float(value)

"""Recognize chat roles and tool-message boundaries, not ordinary vocabulary.

The largest responses are user role labels and tool-call delimiters. The
first message has a stronger start/role response. Smaller boundary responses
also fade with distance from the document's beginning, approximated by simple
inverse-distance curves. Ordinary text and its lexical variations are zero.
"""
from math import sqrt

READS = ()
FIRST_ROLES = {'user': 1.817, 'assistant': 0.968, 'system': 1.631}
FIRST_MARKERS = {
    '<|im_start|>': 1.321,
    '<|im_end|>': 0.645,
    '<tool_call>': 1.771,
    '</tool_call>': 1.786,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous, before_previous = 0, '', ''
    else:
        position = carry[1] + 1
        previous, before_previous = carry[2], carry[3]
    token = prefix.token_strings[-1]
    inverse = 1.0 / (position + 1)
    early = sqrt(inverse)
    value = 0.0
    if token == '<|im_start|>':
        value = -0.049 + 1.333 / (position + 4)
    elif previous == '<|im_start|>':
        if token == 'user':
            value = 1.077 + 0.834 * early
        elif token == 'assistant':
            value = -0.001 + 0.707 / (position + 4)
        if position == 1:
            value = FIRST_ROLES.get(token, value)
    elif token == '<tool_call>':
        value = 1.229
    elif token == '</tool_call>':
        value = 1.431
    elif token == '<tool_response>':
        value = 1.091 + 0.172 * early
    elif token == '</tool_response>':
        value = 0.084 + 2.006 * inverse
    elif token == '<|im_end|>':
        if previous == '</tool_call>':
            value = 0.055 + 1.339 * early
        elif previous == '</tool_response>':
            value = -0.048 + 2.542 * inverse
        else:
            value = -0.161 + 1.927 / (position + 4)
    elif token == '\n' and previous == '<|im_end|>':
        value = 0.037
        if before_previous == '</tool_call>':
            value = 0.089
        elif before_previous == '</tool_response>':
            value = 0.121
    if position == 0:
        value = FIRST_MARKERS.get(token, value)
    return (doc, position, token, previous), float(value)

