    " associated": 0.5, " result": 0.3, " results": 0.2, " effect": 0.3, " lead": 0.4,
    " leading": 0.25, " led": 0.3, " problems": 0.35, " likely": 0.33, " affect": 0.34,
    " stress": 0.5, " face": 0.4, " faced": 0.5, " burden": 0.4, " vulnerable": 0.5, " induce": 0.33,
