programs.sol:
"""Approximate a rare response to English with the letter 'a' lost.

Repeated damaged words, together with scarcity of 'a', raise a running
confidence in text-extraction damage. Short word fragments then receive
positive values, especially 'nd' (and), 're' (are), and consonant starts
of part/rational/base/all. Code punctuation weakens that confidence.
A short prepositional opening also boosts 'nd'. Initial comment/HTML
headers are negative. A few source-code
and conversation delimiters have their own small background responses.
This leaves most weak, token-specific fluctuations unexplained.
"""
import re

READS = ()
WORDS_WITH_A = '''
and that have has was can what part math page equal large same each
state allow spaces compact distance interval integral called angle answer
calculate equation graph partition valued relationship rational
'''.split()
A_DROPPED_WORDS = frozenset(w.replace('a', '') for w in WORDS_WITH_A)
OPENING_PREPOSITIONS = frozenset('for to with from in on at by of'.split())
SHORT_WORDS = frozenset(
    'of to in on at by is be it as or if we do so no he an am us my up go'.split()
)
A_DROPPED_STARTS = frozenset((' prt', ' rt', ' bs', ' ll'))


def damage_level(text):
    lower = text.lower()
    words = re.findall(r'[a-z]+', lower)
    distinct = len(set(words) & A_DROPPED_WORDS)
    letters = sum(map(len, words))
    a_fraction = lower.count('a') / max(1, letters)
    scarcity = min(1.0, max(0.0, (0.04 - a_fraction) / 0.025))
    repeated = min(1.0, max(0.0, (distinct - 1) / 2.0))
    level = max(repeated, scarcity * min(1.0, distinct / 2.0))
    return level * 0.5 ** sum(text.count(c) for c in '{};')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, old_damage = ('', 0.0) if first else carry[1:]
    token = prefix.token_strings[-1]
    text = (previous + token)[-320:]
    damage = max(damage_level(text), old_damage * 0.995)
    if any(c in token for c in '{};'):
        damage *= 0.7

    word = token.strip()
    value = -0.00086
    if token == ' nd':
        value = 0.15 + 0.35 * damage
        if previous.strip().lower() in OPENING_PREPOSITIONS:
            value = 0.55
    elif token == ' re':
        value = 0.025 + 0.33 * damage
    elif token in (' th', ' cn', ' hs', ' ws'):
        value = -0.015 + 0.27 * damage
    elif damage and word.isascii() and word.isalpha():
        value = 0.055 * damage
        if token.startswith(' ') and word.islower():
            if len(word) == 1:
                value = (0.23 if word == 's' else 0.14) * damage
            elif len(word) <= 3 and word not in SHORT_WORDS:
                value = 0.23 * damage
                if token in A_DROPPED_STARTS:
                    value = 0.42 * damage
    elif damage and token == '###':
        value = 0.10 * damage

    # Small formatting responses outside damaged prose.
    if token == '</think>':
        value = 0.186
    elif token == '<|im_end|>':
        value = -0.025
    elif token == '\r':
        value = 0.12
    elif token == 'import':
        value = 0.151 if first else 0.05
    elif token.startswith('_'):
        value -= 0.012
    elif word.startswith('@'):
        value -= 0.030
    if first:
        if token == '//\n':
            value = -0.334
        elif token == '<!':
            value = -0.437
    return (doc, text, damage), float(value)

