    if token in ('built', ' built'):
        return -0.08
    if token.startswith(' ') and token.strip().lower() in COGNITION:
        return 0.09
    return -0.0015


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old_doc, tail = carry if carry is not None else (None, '')
    first = doc != old_doc
