"""A negative comma response, strongest in Chinese clauses.

The preceding token's script and the fraction of recent tokens containing Han
characters set the response. Fullwidth commas after very short clauses are
weaker. Selected comma forms bundled with words or punctuation are attenuated.
Other punctuation has small fixed responses; other tokens are inactive.
All history is reset at a document boundary.
"""
from collections import deque

READS = ()
CLAUSE_ENDS = frozenset(',，。.!?！？；;:\n')
SMALL_PUNCTUATION = {'،': -0.75, '；': -0.54, '：': -0.27,
                     '、': 0.09, '！': -0.16}


def han_count(text):
    return sum('\u3400' <= c <= '\u9fff' or '\uf900' <= c <= '\ufaff'
               for c in text)


def in_range(text, low, high):
    return any(low <= c <= high for c in text)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, deque(maxlen=32), '', 1)
    _, history, previous, clause_length = carry
    token = prefix.token_strings[-1]
    value = SMALL_PUNCTUATION.get(token, 0.0)

    if '，' in token or ',' in token:
        han = han_count(previous)
        density32 = sum(history) / max(1, len(history))
        density4 = sum(list(history)[-4:]) / max(1, min(4, len(history)))
        extra_han = max(0, han - 1)
        if '，' in token:
            value = (-1.48 - 0.52 * bool(han) - 0.74 * density4
                     - 1.09 * density32 - 0.13 * extra_han
                     + 1.82 / clause_length
                     + 0.48 * any(c.isdigit() for c in previous))
            if not history and token == '，':
                value = -0.32
            elif token == '%，':
                value = -2.30
            elif '\n\n' in token:
                value *= 0.25
            elif '\n' in token:
                value *= 0.34
            elif any(c.isalpha() for c in token):
                value *= 0.63
            elif token.endswith('，') and any(c in token for c in '”》」』'):
                value *= 0.87
            elif token.startswith('，') and any(c in token for c in '“《「『'):
                value *= 0.45
            elif '。' in token:
                value *= 0.38
            elif any(c in token for c in '()（）'):
                value *= 0.85
        else:
            comma = (-0.01 - 0.81 * bool(han) - 1.26 * density4
                     - 1.34 * density32 - 0.13 * extra_han
                     - 0.79 * in_range(previous, '\uac00', '\ud7af')  # Hangul
                     - 0.66 * in_range(previous, '\u3040', '\u30ff')  # Kana
                     - 0.26 * in_range(previous, '\u0400', '\u04ff')  # Cyrillic
                     - 0.42 * any('\u0600' <= c <= '\u06ff' and c.isalpha()
                                  for c in previous)  # Arabic letters
                     - 0.56 * (in_range(previous, '\u1ea0', '\u1eff')
                               or any(c in 'ăĂơƠưƯđĐ' for c in previous)))
            # The last term detects Vietnamese-specific letters.
            if token == ',':
                value = comma if history else 0.03
            elif token == '%,':
                value = -0.55
            elif token == ',\n':
                value = 0.13 + 0.30 * comma
            elif token == ' ,':
                value = 0.07 + 0.50 * comma
            elif token == ',,':
                value = 0.45 * comma
            elif token == '(),':
                value = 0.19
            elif token.endswith(',') and any(c in token for c in ')]}'):
                value = -0.10 + 0.30 * comma

    history.append(bool(han_count(token)))
    clause_length = (1 if any(c in CLAUSE_ENDS for c in token)
                     else clause_length + 1)
    return (doc, history, token, clause_length), float(value)

programs.haiku:
"""Chinese-comma detector for layers.0.mlp.down_proj:4605.

This component is a comma detector that is silent in English and strongly negative in
Chinese text. Its activation is:
  - the full-width comma "，" (and tokens that contain it, such as "，在"): strongly negative,
    about -2 to -3.5, and more negative when more Chinese text comes before it;
  - the ASCII comma "," when it directly follows Chinese text: strongly negative, scaled by
    how much of the recent text is Chinese (about 0 after English text, as in most ASCII commas);
  - the semicolon "；", colon "：" and Arabic comma "،": mildly negative;
  - everything else: about 0.
The program tracks the share of CJK characters in the last 16 characters of text.
"""

READS = ()


def is_cjk(ch):
    return "一" <= ch <= "鿿" or "぀" <= ch <= "ヿ" or "가" <= ch <= "힯"


def chinese_share(prefix, window=16):
    """Fraction of the characters in the last `window` tokens that are CJK."""
    text = "".join(prefix.token_strings[-window - 1:-1])
    if not text:
        return 0.0
    return sum(is_cjk(c) for c in text) / len(text)


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    share = chinese_share(prefix)
    if tok == "，":
        return None, -2.0 - 1.5 * share
    if "，" in tok:
        return None, -2.2
    if tok == ",":
        return None, -3.0 * share
    if tok in ("；", "：", "،"):
        return None, -0.5
    return None, 0.0

programs.luna:
"""A comma is a useful but noisy cue: single Chinese and ASCII commas
get the strongest small negative estimate, with weaker estimates when
comma punctuation is part of a longer token or another separator appears."""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == "，":
        value = -0.33
    elif token == ",":
        value = -0.25
    elif any(mark in token for mark in "，,"):
        value = -0.10
    elif any(mark in token for mark in "،；;："):
        value = -0.06
    else:
        value = 0.0
    return None, value

programs.sol:
"""Local noun-phrase contrasts, especially the word immediately after 'the'.

Small cardinal numbers and selected modifiers are positive. Selected abstract
heads are negative, particularly 'the fact', 'the importance', and nouns that
introduce complements. Weaker number responses follow other determiners.
This is a lexical approximation, not a general part-of-speech tagger.
"""
import math

READS = ()

CARDINALS = ('one', 'two', 'three', 'four', 'five', 'six', 'seven',
             'eight', 'nine', 'ten', 'eleven', 'twelve')
QUANTITY = {
    'other': 1.95, 'others': 1.95, 'only': 1.87, 'more': 2.12,
    'different': 2.28, 'various': 2.28, 'several': 1.88,
    'many': 1.44, 'few': 1.27, 'little': 1.30, 'less': 1.20,
    'much': 1.20, 'single': 0.97, 'double': 0.92,
}
COMPARATIVES = set('''larger smaller higher lower longer shorter bigger
    better greater deeper harder simpler'''.split())
MODIFIERS = set('''new main real simple relevant great major individual
    specific very long big large missing bad unknown hard'''.split())
ABSTRACT_HEADS = set('''need ability possibility necessity idea notion sense
    use sight'''.split())
EXISTENCE = set('presence absence existence occurrence essence'.split())
NOMINAL_HEADS = set('''form formation invention creation opportunity choice
    concept appearance chance phrase aid midst'''.split())
COMMON_HEADS = set('''end age way country university city board event effect
    effects role origin extent art context property purpose author title help
    nation story town face place world strength realm spot course'''.split())
PROCESS_HEADS = set('''development statement expression conclusion practice
    introduction definition production release effectiveness'''.split())
POSSESSIVES = set('my your his her its our their'.split())


def number_strength(word):
    if word not in CARDINALS:
        return 0.0
    n = CARDINALS.index(word) + 1
    # 'Two' is strongest; larger counts have progressively weaker responses.
    return 1.4 if n == 1 else max(0.7, 5.2 - 1.6 * math.log(n))


def after_the(token):
    word = token.strip().lower()
    if token == ' ':
        return 1.36
    value = number_strength(word)
    if value:
        if token.strip().istitle():
            value *= 0.76
        return value
    if word in QUANTITY:
        return QUANTITY[word]
    if word == 'fact':
        return -3.1
    if word == 'importance':
        return -2.0
    if word in ABSTRACT_HEADS:
        return -1.65
    if word in EXISTENCE:
        return -1.4
    if word in NOMINAL_HEADS:
        return -1.1
    if word in {'day', 'morning'}:
        return -0.9
    if word in COMMON_HEADS:
        return -0.6
    if word in PROCESS_HEADS:
        return -0.8
    if word in COMPARATIVES:
        return 0.9
    if word in MODIFIERS:
        return 0.85 if token.strip().islower() else 0.25
    if word in {'above', 'outside'}:
        return 1.1
    if word.endswith(('tion', 'sion', 'ment', 'ness', 'ity')):
        return -0.25 if token.strip().islower() else 0.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before = '', ''
    else:
        _, previous, before = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    last = previous.strip().lower()
    earlier = before.strip().lower()
    value = 0.0
    if last == 'the':
        value = after_the(token)
    elif (earlier == 'the' and previous == ' '
          and word.isascii() and word.isdigit()):
        value = 0.66 if word == '1' else 1.1 if word == '2' else 0.85
    elif last == 'let' and word in {'me', 'us', "'s", '’s'}:
        value = 0.65 if word == 'us' else 0.92
    elif earlier == 'the' and last in {'set', 'list'} and word == 'of':
        value = 0.7
    elif earlier == 'the' and last == 'ability' and word == 'to':
        value = -0.85
    elif number_strength(word):
        strength = number_strength(word)
        if last == 'all':
            value = 0.54 * strength
        elif last in {'these', 'those', 'any', 'other', 'same'} | POSSESSIVES:
            value = 0.33 * strength
        elif last in {'are', 'were'}:
            value = 0.22 * strength
        elif last == 'no':
            value = 0.15 * strength
    elif word in {'other', 'others'}:
        if last == 'all':
            value = 0.95
        elif last == 'any':
            value = 0.4
    return (doc, token, previous), value

programs.haiku:
"""Layer-0 MLP unit (down_proj component 4606): a "word after 'the'" detector.

It is silent almost everywhere. It responds to the word that directly follows "the"
(any case, with or without a leading space), and to a number word after "these", "those",
"all", "are", "its", etc.:
  * number words (two, three, four, ...) and "other", "different", "various", "more", "only":
    strongly positive ("the two", "the other", "the four");
  * a space token before a digit ("the 2"): positive;
  * abstract nouns that usually take an "of" or "that" complement (fact, importance,
    possibility, idea, need, ability, ...): negative ("the fact that"); other nouns ending in
    -tion, -ment, -ance, -ence, -ity, -ness, -ism, -ship: mildly negative.
"Let me" and "let's" give a moderate positive response on "me" and "'s".
Everything else is 0 (the activation's typical value is about 0, with spikes of +/-1 to +4).
"""

READS = ()
NOMINAL_SUFFIXES = ("tion", "sion", "ment", "ance", "ence", "ity", "ness", "ism", "ship")

DETERMINERS = {"the"}
WEAK_DETERMINERS = {"these", "those", "all", "are", "were", "its", "his", "our", "any", "no", "both"}
NUMBER_VALUES = {
    "two": 4.0, "three": 3.4, "four": 3.1, "five": 2.4, "six": 2.0, "seven": 2.0, "eight": 1.9,
    "nine": 2.0, "one": 1.4, "ten": 1.0, "many": 1.5, "few": 1.3, "several": 1.8,
}
POSITIVE_WORDS = {"other", "different", "various", "more", "only", "above", "new", "main", "major",
                  "great", "single", "real", "large", "individual"}
COMPLEMENT_NOUNS = {"fact", "importance", "possibility", "idea", "need", "ability", "existence",
                    "presence", "use", "sense", "absence", "formation", "form", "opportunity",
                    "invention", "concept", "creation", "principle", "effect", "role", "extent", "choice"}


def step(carry, prefix, upstream):
    s = prefix.token_strings
    if len(s) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    prev = s[-2].strip().lower()
    word = s[-1].strip().lower()
    if prev in DETERMINERS:
        if s[-1] == " ":
            return None, 1.4
        if word in NUMBER_VALUES:
            return None, NUMBER_VALUES[word]
        if word in POSITIVE_WORDS:
            return None, 1.8
        if word in COMPLEMENT_NOUNS:
            return None, -1.5
        if word.endswith(NOMINAL_SUFFIXES):
            return None, -0.4
        return None, 0.0
    if prev in WEAK_DETERMINERS and word in NUMBER_VALUES:
        return None, 0.5 * NUMBER_VALUES[word]
    if prev == "let" and word in ("me", "'s"):
        return None, 0.9
    return None, 0.0
